{
  "name": "contract-guard",
  "version": "0.1.0",
  "private": true,
  "description": "API contract registry: validates OpenAPI specs, diffs versions, checks consumer impact, and blocks breaking publications.",
  "type": "module",
  "engines": {
    "node": ">=22"
  },
  "main": "dist/server.js",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "dev": "tsx watch src/server.ts",
    "start": "node dist/server.js",
    "test": "vitest run",
    "test:watch": "vitest"
  }
}

/**
 * Configuration for Contract Guard, read from environment variables.
 *
 * Every value is validated. `loadConfig` throws a `ConfigError` that lists ALL
 * problems at once with the offending variable named, so a misconfigured
 * startup fails clearly and immediately instead of failing partially later.
 */

export const GATE_MODES = ["consumer", "strict"] as const;
export type GateMode = (typeof GATE_MODES)[number];

export interface Config {
  /** HTTP port for the Contract Guard API + dashboard. */
  port: number;
  /** Base URL of the webhook receiver that stands in for chat/email. */
  webhookUrl: string;
  /** SQLite file path, or ":memory:" for tests. */
  dbPath: string;
  /** "Today" used for `x-sunset` comparisons. Defaults to the real date. */
  asOfDate: Date;
  /** Whether the pinned as-of date came from CG_AS_OF_DATE (true) or the clock (false). */
  asOfDatePinned: boolean;
  /** Gate policy. Default "consumer" (locked decision L-1). */
  gateMode: GateMode;
  /** Replay the whole pipeline at startup (locked decision L-3). Default true. */
  fresh: boolean;
  /** Folder containing the read-only `specs/` and `consumers/` directories. */
  kitRoot: string;
  /** Absolute path to this app's own directory. */
  appRoot: string;
}

export class ConfigError extends Error {
  readonly problems: string[];

  constructor(problems: string[]) {
    super(`invalid configuration:\n${problems.map((p) => `  - ${p}`).join("\n")}`);
    this.name = "ConfigError";
    this.problems = problems;
  }
}

const DEFAULT_WEBHOOK_URL = "http://localhost:9900";
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Parse an integer env var within [min, max]; never throws, records problems instead. */
function readPort(
  env: NodeJS.ProcessEnv,
  problems: string[],
): number | undefined {
  const raw = env.PORT;
  if (raw === undefined || raw.trim() === "") return 5000;
  const value = Number(raw.trim());
  if (!Number.isInteger(value) || value < 1 || value > 65_535) {
    problems.push(`PORT must be an integer between 1 and 65535, got ${JSON.stringify(raw)}`);
    return undefined;
  }
  return value;
}

function readWebhookUrl(
  env: NodeJS.ProcessEnv,
  problems: string[],
): string | undefined {
  const raw = env.WEBHOOK_URL?.trim() || DEFAULT_WEBHOOK_URL;
  let parsed: URL;
  try {
    parsed = new URL(raw);
  } catch {
    problems.push(`WEBHOOK_URL must be an absolute http(s) URL, got ${JSON.stringify(raw)}`);
    return undefined;
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    problems.push(`WEBHOOK_URL must use http or https, got ${JSON.stringify(raw)}`);
    return undefined;
  }
  return parsed.toString().replace(/\/$/, "");
}

/**
 * `x-sunset` dates are calendar dates in IST (locked decision L-4). The as-of
 * date is likewise interpreted as the IST calendar date, at 00:00 UTC so it is
 * directly comparable with parsed sunset dates.
 */
function readAsOfDate(
  env: NodeJS.ProcessEnv,
  problems: string[],
): { date: Date; pinned: boolean } | undefined {
  const raw = env.CG_AS_OF_DATE?.trim();
  if (raw === undefined || raw === "") {
    return { date: istCalendarDate(new Date()), pinned: false };
  }
  if (!ISO_DATE.test(raw)) {
    problems.push(`CG_AS_OF_DATE must be YYYY-MM-DD, got ${JSON.stringify(raw)}`);
    return undefined;
  }
  const [year, month, day] = raw.split("-").map(Number) as [number, number, number];
  // Reject impossible dates such as 2026-02-31, which Date would silently roll over.
  if (month < 1 || month > 12 || day < 1 || day > 31) {
    problems.push(`CG_AS_OF_DATE must be a real calendar date, got ${JSON.stringify(raw)}`);
    return undefined;
  }
  const probe = new Date(Date.UTC(year, month - 1, day));
  if (probe.getUTCMonth() !== month - 1 || probe.getUTCDate() !== day) {
    problems.push(`CG_AS_OF_DATE must be a real calendar date, got ${JSON.stringify(raw)}`);
    return undefined;
  }
  return { date: probe, pinned: true };
}

/** Reduce an instant to its IST calendar date, normalised to 00:00 UTC. */
export function istCalendarDate(instant: Date): Date {
  const ist = new Date(instant.getTime() + 5.5 * 60 * 60 * 1000);
  return new Date(Date.UTC(ist.getUTCFullYear(), ist.getUTCMonth(), ist.getUTCDate()));
}

function readGateMode(
  env: NodeJS.ProcessEnv,
  problems: string[],
): GateMode | undefined {
  const raw = env.GATE_MODE?.trim().toLowerCase() || "consumer";
  if (!GATE_MODES.includes(raw as GateMode)) {
    problems.push(`GATE_MODE must be one of ${GATE_MODES.join(", ")}, got ${JSON.stringify(env.GATE_MODE)}`);
    return undefined;
  }
  return raw as GateMode;
}

/** `CG_FRESH` defaults to enabled: demos must replay the pipeline on every launch. */
function readFresh(env: NodeJS.ProcessEnv, problems: string[]): boolean | undefined {
  const raw = env.CG_FRESH?.trim().toLowerCase();
  if (raw === undefined || raw === "") return true;
  if (["1", "true", "yes", "on"].includes(raw)) return true;
  if (["0", "false", "no", "off"].includes(raw)) return false;
  problems.push(`CG_FRESH must be a boolean (1/0, true/false), got ${JSON.stringify(env.CG_FRESH)}`);
  return undefined;
}

/**
 * Resolve configuration from an environment object.
 * @throws {ConfigError} when any variable is missing-or-malformed.
 */
export function loadConfig(
  env: NodeJS.ProcessEnv = process.env,
  appRoot = process.cwd(),
): Config {
  const problems: string[] = [];

  const port = readPort(env, problems);
  const webhookUrl = readWebhookUrl(env, problems);
  const asOf = readAsOfDate(env, problems);
  const gateMode = readGateMode(env, problems);
  const fresh = readFresh(env, problems);

  const dbPath = env.CG_DB_PATH?.trim() || `${appRoot}/data/contract-guard.db`;

  if (problems.length > 0) throw new ConfigError(problems);

  return {
    port: port as number,
    webhookUrl: webhookUrl as string,
    dbPath,
    asOfDate: (asOf as { date: Date }).date,
    asOfDatePinned: (asOf as { pinned: boolean }).pinned,
    gateMode: gateMode as GateMode,
    fresh: fresh as boolean,
    kitRoot: env.KIT_ROOT?.trim() || `${appRoot}/..`,
    appRoot,
  };
}

/**
 * Minimal leveled logger. No dependency: the receiver and demo need readable
 * startup output, not a logging framework.
 */

export const LEVELS = ["debug", "info", "warn", "error"] as const;
export type Level = (typeof LEVELS)[number];

export interface Logger {
  debug(message: string, fields?: Record<string, unknown>): void;
  info(message: string, fields?: Record<string, unknown>): void;
  warn(message: string, fields?: Record<string, unknown>): void;
  error(message: string, fields?: Record<string, unknown>): void;
  child(bindings: Record<string, unknown>): Logger;
}

function thresholdFor(name: string): number {
  const index = LEVELS.indexOf(name.trim().toLowerCase() as Level);
  return index === -1 ? LEVELS.indexOf("info") : index;
}

function format(level: Level, message: string, bindings: Record<string, unknown>): string {
  const stamp = new Date().toISOString();
  const extras = Object.keys(bindings).length
    ? ` ${Object.entries(bindings)
        .map(([key, value]) => `${key}=${typeof value === "string" ? value : JSON.stringify(value)}`)
        .join(" ")}`
    : "";
  return `${stamp} ${level.toUpperCase().padEnd(5)} ${message}${extras}`;
}

function emit(
  stream: (line: string) => void,
  minIndex: number,
  bindings: Record<string, unknown>,
): Logger {
  const make = (level: Level) => (message: string, fields?: Record<string, unknown>) => {
    if (LEVELS.indexOf(level) < minIndex) return;
    stream(format(level, message, { ...bindings, ...fields }));
  };
  return {
    debug: make("debug"),
    info: make("info"),
    warn: make("warn"),
    error: make("error"),
    child: (extra) => emit(stream, minIndex, { ...bindings, ...extra }),
  };
}

export function createLogger(options: { level?: string } = {}): Logger {
  const minIndex = thresholdFor(options.level ?? "info");
  const stdout = (line: string) => process.stdout.write(`${line}\n`);
  const stderr = (line: string) => process.stderr.write(`${line}\n`);
  const base = emit<Level>((line) => stdout(line), minIndex, {});
  // Route warn/error to stderr while keeping the same formatting and level.
  const errStream = emit<Level>((line) => stderr(line), minIndex, {});
  return {
    ...base,
    warn: errStream.warn,
    error: errStream.error,
  };
}

/**
 * SQLite access layer (locked decision T-2: better-sqlite3, synchronous).
 *
 * `openDatabase` creates the directory for a file-backed DB, applies pending
 * migrations idempotently, and returns a ready handle. Migrations are applied
 * one per transaction and recorded, so calling `openDatabase` again on the same
 * file is safe and does nothing.
 */
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { DatabaseSync } from "node:sqlite";

import { MIGRATIONS, type Migration } from "./migrations.ts";

export type Database = DatabaseSync;

const MIGRATIONS_TABLE = `
CREATE TABLE IF NOT EXISTS schema_migrations (
  id         TEXT PRIMARY KEY,
  applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);`;

function appliedMigrationIds(db: Database): Set<string> {
  const rows = db.prepare("SELECT id FROM schema_migrations").all() as Array<{ id: string }>;
  return new Set(rows.map((row) => row.id));
}

/** Apply pending migrations in order. Returns the ids applied by this call. */
export function runMigrations(db: Database, migrations: Migration[] = MIGRATIONS): string[] {
  db.exec(MIGRATIONS_TABLE);
  const applied = appliedMigrationIds(db);
  const pending = [...migrations]
    .sort((a, b) => a.id.localeCompare(b.id))
    .filter((migration) => !applied.has(migration.id));

  const record = db.prepare("INSERT INTO schema_migrations (id) VALUES (?)");
  const done: string[] = [];
  for (const migration of pending) {
    // better-sqlite3 has no transaction helper for arbitrary multi-statement
    // SQL, so drive BEGIN/COMMIT manually and roll back on any failure.
    db.exec("BEGIN");
    try {
      db.exec(migration.sql);
      record.run(migration.id);
      db.exec("COMMIT");
      done.push(migration.id);
    } catch (error) {
      db.exec("ROLLBACK");
      throw new Error(
        `migration ${migration.id} (${migration.description}) failed: ${(error as Error).message}`,
      );
    }
  }
  return done;
}

export interface OpenDatabaseOptions {
  /** File path, or ":memory:". */
  path: string;
  migrations?: Migration[];
}

export function openDatabase({ path, migrations }: OpenDatabaseOptions): {
  db: Database;
  applied: string[];
} {
  if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec("PRAGMA journal_mode = WAL;");
  db.exec("PRAGMA foreign_keys = ON;");
  const applied = runMigrations(db, migrations);
  return { db, applied };
}

/** Migrations already recorded, for the health endpoint and tests. */
export function migrationStatus(db: Database): { applied: string[]; pending: string[] } {
  const applied = [...appliedMigrationIds(db)].sort();
  const pending = MIGRATIONS.map((m) => m.id)
    .filter((id) => !applied.includes(id))
    .sort();
  return { applied, pending };
}

/**
 * SQLite access layer (locked decision T-2: better-sqlite3, synchronous API).
 *
 * `openDatabase` creates the directory for a file-backed DB, applies pending
 * migrations idempotently, and returns a ready handle. Each migration runs in
 * its own transaction and is recorded in `schema_migrations`, so calling
 * `openDatabase` again on the same file is a safe no-op.
 */
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import BetterSqlite3 from "better-sqlite3";

import { MIGRATIONS, type Migration } from "./migrations.js";

export type Database = BetterSqlite3.Database;

const MIGRATIONS_TABLE = `
CREATE TABLE IF NOT EXISTS schema_migrations (
  id         TEXT PRIMARY KEY,
  applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);`;

function appliedMigrationIds(db: Database): Set<string> {
  const rows = db.prepare("SELECT id FROM schema_migrations").all() as Array<{ id: string }>;
  return new Set(rows.map((row) => row.id));
}

/** Apply pending migrations in order. Returns the ids applied by this call. */
export function runMigrations(db: Database, migrations: Migration[] = MIGRATIONS): string[] {
  db.exec(MIGRATIONS_TABLE);
  const applied = appliedMigrationIds(db);
  const pending = [...migrations]
    .sort((a, b) => a.id.localeCompare(b.id))
    .filter((migration) => !applied.has(migration.id));

  const record = db.prepare("INSERT INTO schema_migrations (id) VALUES (?)");
  const justApplied: string[] = [];
  for (const migration of pending) {
    // One transaction per migration: schema + its record commit together, or not at all.
    const apply = db.transaction(() => {
      db.exec(migration.sql);
      record.run(migration.id);
    });
    try {
      apply();
      justApplied.push(migration.id);
    } catch (error) {
      throw new Error(
        `migration ${migration.id} (${migration.description}) failed: ${(error as Error).message}`,
      );
    }
  }
  return justApplied;
}

export interface OpenDatabaseOptions {
  /** File path, or ":memory:". */
  path: string;
  migrations?: Migration[];
}

export function openDatabase({ path, migrations }: OpenDatabaseOptions): {
  db: Database;
  applied: string[];
} {
  if (path !== ":memory:") mkdirSync(dirname(path), { recursive: true });
  const db = new BetterSqlite3(path);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  const applied = runMigrations(db, migrations);
  return { db, applied };
}

/** Migrations recorded vs still pending, for the health endpoint and tests. */
export function migrationStatus(db: Database): { applied: string[]; pending: string[] } {
  const applied = [...appliedMigrationIds(db)].sort();
  const pending = MIGRATIONS.map((m) => m.id)
    .filter((id) => !applied.includes(id))
    .sort();
  return { applied, pending };
}

/**
 * Express application factory. Kept free of `listen` and process wiring so the
 * same app can be driven by supertest in tests and by server.ts in production.
 */
import express, { type Express, type NextFunction, type Request, type Response } from "express";

import type { Config } from "./config.js";
import type { Database } from "./db/database.js";
import { migrationStatus } from "./db/database.js";
import type { Logger } from "./logger.js";

export const APP_NAME = "contract-guard";
export const APP_VERSION = "0.1.0";

export interface AppDependencies {
  config: Config;
  db: Database;
  logger: Logger;
  /** When the process started — reported by /api/health. */
  startedAt?: Date;
}

export function createApp({ config, db, logger, startedAt = new Date() }: AppDependencies): Express {
  const app = express();
  app.disable("x-powered-by");
  app.use(express.json({ limit: "4mb" }));

  app.get("/api/health", (_req: Request, res: Response) => {
    let dbHealth: { ok: boolean; migrations: string[]; pending: string[]; error?: string };
    try {
      const { applied, pending } = migrationStatus(db);
      dbHealth = { ok: pending.length === 0, migrations: applied, pending };
    } catch (error) {
      dbHealth = { ok: false, migrations: [], pending: [], error: (error as Error).message };
    }

    const healthy = dbHealth.ok;
    res.status(healthy ? 200 : 503).json({
      status: healthy ? "ok" : "degraded",
      service: APP_NAME,
      version: APP_VERSION,
      uptimeSeconds: Math.round((Date.now() - startedAt.getTime()) / 1000),
      gateMode: config.gateMode,
      asOfDate: config.asOfDate.toISOString().slice(0, 10),
      asOfDatePinned: config.asOfDatePinned,
      fresh: config.fresh,
      webhookUrl: config.webhookUrl,
      db: dbHealth,
    });
  });

  app.use((_req, res) => {
    res.status(404).json({ error: "not_found" });
  });

  app.use((error: Error, _req: Request, res: Response, _next: NextFunction) => {
    logger.error("unhandled request error", { message: error.message });
    res.status(500).json({ error: "internal_error" });
  });

  return app;
}

/**
 * Process entry point: configuration, database, HTTP server.
 *
 * Phases 1+ plug the loader, engines, gate, notifier and startup pipeline in
 * here; Phase 0 establishes the foundation only.
 */
import { createApp, APP_NAME, APP_VERSION } from "./app.js";
import { ConfigError, loadConfig } from "./config.js";
import { openDatabase } from "./db/database.js";
import { createLogger } from "./logger.js";

function main(): void {
  const logger = createLogger({ level: process.env.CG_LOG_LEVEL });

  let config;
  try {
    config = loadConfig(process.env, process.cwd());
  } catch (error) {
    if (error instanceof ConfigError) {
      logger.error("startup aborted", { problems: error.problems.join(" | ") });
      process.exit(1);
    }
    throw error;
  }

  const { db, applied } = openDatabase({ path: config.dbPath });
  if (applied.length) logger.info("migrations applied", { ids: applied.join(",") });

  const app = createApp({ config, db, logger });
  const server = app.listen(config.port, () => {
    logger.info(`${APP_NAME} ${APP_VERSION} listening`, {
      port: config.port,
      gateMode: config.gateMode,
      asOfDate: config.asOfDate.toISOString().slice(0, 10),
      asOfDatePinned: config.asOfDatePinned,
      fresh: config.fresh,
      dbPath: config.dbPath,
      webhookUrl: config.webhookUrl,
    });
  });

  const shutdown = (signal: string) => {
    logger.info("shutting down", { signal });
    server.close(() => {
      db.close();
      process.exit(0);
    });
  };
  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}

main();

import { defineConfig } from "vitest/config";

export default defineConfig({
  resolve: {
    // Source files use NodeNext-style ".js" specifiers; map them to ".ts" for tests.
    extensionAlias: { ".js": [".ts", ".js"] },
  },
  test: {
    include: ["test/**/*.test.ts"],
    environment: "node",
    globals: false,
    pool: "forks",
  },
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeEach, describe, expect, it } from "vitest";

import { ConfigError, istCalendarDate, loadConfig } from "../src/config.js";

/** Minimal environment that always passes validation. */
function baseEnv(): NodeJS.ProcessEnv {
  return { CG_DB_PATH: ":memory:" };
}

describe("loadConfig defaults", () => {
  let env: NodeJS.ProcessEnv;
  beforeEach(() => {
    env = baseEnv();
  });

  it("uses the locked defaults from PLAN.md §4", () => {
    const config = loadConfig(env, "/app");
    expect(config.port).toBe(5000);
    expect(config.webhookUrl).toBe("http://localhost:9900");
    expect(config.gateMode).toBe("consumer");
    expect(config.fresh).toBe(true);
    expect(config.dbPath).toBe(":memory:");
    expect(config.appRoot).toBe("/app");
  });

  it("falls back to data/contract-guard.db under the app root", () => {
    const config = loadConfig({}, "/srv/app");
    expect(config.dbPath).toBe("/srv/app/data/contract-guard.db");
  });

  it("resolves the kit root to the parent of the app by default", () => {
    expect(loadConfig({}, "/srv/app").kitRoot).toBe("/srv/app/..");
    expect(loadConfig({ KIT_ROOT: "/kit" }, "/srv/app").kitRoot).toBe("/kit");
  });

  it("defaults the as-of date to today's IST calendar date, unpinned", () => {
    const config = loadConfig(env, "/app");
    expect(config.asOfDatePinned).toBe(false);
    expect(config.asOfDate).toEqual(istCalendarDate(new Date()));
  });
});

describe("loadConfig overrides", () => {
  it("reads every supported variable", () => {
    const config = loadConfig(
      {
        PORT: "4321",
        WEBHOOK_URL: "http://receiver:9000/",
        CG_DB_PATH: "/tmp/cg.db",
        CG_AS_OF_DATE: "2026-11-18",
        GATE_MODE: "strict",
        CG_FRESH: "0",
        KIT_ROOT: "/kit",
      },
      "/app",
    );
    expect(config.port).toBe(4321);
    expect(config.webhookUrl).toBe("http://receiver:9000");
    expect(config.dbPath).toBe("/tmp/cg.db");
    expect(config.asOfDate.toISOString()).toBe("2026-11-18T00:00:00.000Z");
    expect(config.asOfDatePinned).toBe(true);
    expect(config.gateMode).toBe("strict");
    expect(config.fresh).toBe(false);
  });

  it("accepts boolean spellings for CG_FRESH", () => {
    for (const raw of ["1", "true", "TRUE", "yes", "on"]) {
      expect(loadConfig({ ...baseEnv(), CG_FRESH: raw }, "/app").fresh).toBe(true);
    }
    for (const raw of ["0", "false", "FALSE", "no", "off"]) {
      expect(loadConfig({ ...baseEnv(), CG_FRESH: raw }, "/app").fresh).toBe(false);
    }
  });

  it("treats empty strings as unset", () => {
    const config = loadConfig({ PORT: "", GATE_MODE: "", CG_FRESH: "", WEBHOOK_URL: "  " }, "/app");
    expect(config.port).toBe(5000);
    expect(config.gateMode).toBe("consumer");
    expect(config.fresh).toBe(true);
    expect(config.webhookUrl).toBe("http://localhost:9900");
  });
});

describe("loadConfig rejects invalid input clearly", () => {
  it("names the offending variable for each bad value", () => {
    const cases: Array<[NodeJS.ProcessEnv, RegExp]> = [
      [{ PORT: "abc" }, /PORT must be an integer between 1 and 65535, got "abc"/],
      [{ PORT: "0" }, /PORT/],
      [{ PORT: "70000" }, /PORT/],
      [{ PORT: "1.5" }, /PORT/],
      [{ WEBHOOK_URL: "not-a-url" }, /WEBHOOK_URL must be an absolute http\(s\) URL, got "not-a-url"/],
      [{ WEBHOOK_URL: "ftp://host:21" }, /WEBHOOK_URL must use http or https/],
      [{ CG_AS_OF_DATE: "18-11-2026" }, /CG_AS_OF_DATE must be YYYY-MM-DD, got "18-11-2026"/],
      [{ CG_AS_OF_DATE: "2026-02-31" }, /CG_AS_OF_DATE must be a real calendar date/],
      [{ CG_AS_OF_DATE: "2026-13-01" }, /CG_AS_OF_DATE must be a real calendar date/],
      [{ GATE_MODE: "yolo" }, /GATE_MODE must be one of consumer, strict, got "yolo"/],
      [{ CG_FRESH: "maybe" }, /CG_FRESH must be a boolean \(1\/0, true\/false\), got "maybe"/],
    ];

    for (const [overrides, pattern] of cases) {
      expect(() => loadConfig({ ...baseEnv(), ...overrides }, "/app")).toThrow(ConfigError);
      try {
        loadConfig({ ...baseEnv(), ...overrides }, "/app");
      } catch (error) {
        expect((error as Error).message).toMatch(pattern);
      }
    }
  });

  it("reports every problem at once instead of failing one at a time", () => {
    let caught: ConfigError | undefined;
    try {
      loadConfig({ PORT: "nope", GATE_MODE: "yolo", CG_FRESH: "maybe" }, "/app");
    } catch (error) {
      caught = error as ConfigError;
    }
    expect(caught).toBeInstanceOf(ConfigError);
    expect(caught?.problems).toHaveLength(3);
    expect(caught?.message).toContain("invalid configuration:");
  });

  it("leaves no partial result behind", () => {
    expect(() => loadConfig({ PORT: "nope" }, "/app")).toThrow(/PORT/);
  });
});

describe("istCalendarDate", () => {
  it("maps an instant to its IST calendar date at 00:00 UTC", () => {
    // 2026-11-17T19:00:00Z is 2026-11-18T00:30 IST.
    expect(istCalendarDate(new Date("2026-11-17T19:00:00Z")).toISOString()).toBe(
      "2026-11-18T00:00:00.000Z",
    );
    // 2026-11-18T18:00:00Z is still 2026-11-18 in IST (23:30).
    expect(istCalendarDate(new Date("2026-11-18T18:00:00Z")).toISOString()).toBe(
      "2026-11-18T00:00:00.000Z",
    );
  });

  it("rolls forward across the IST midnight boundary", () => {
    expect(istCalendarDate(new Date("2026-11-18T19:00:00Z")).toISOString()).toBe(
      "2026-11-19T00:00:00.000Z",
    );
  });
});

describe("temp database path handling", () => {
  const dirs: string[] = [];
  afterAll(() => {
    for (const dir of dirs) rmSync(dir, { recursive: true, force: true });
  });

  it("keeps a caller-supplied db path untouched", () => {
    const dir = mkdtempSync(join(tmpdir(), "cg-config-"));
    dirs.push(dir);
    const target = join(dir, "nested", "cg.db");
    expect(loadConfig({ CG_DB_PATH: target }, "/app").dbPath).toBe(target);
  });
});

import { mkdtempSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import BetterSqlite3 from "better-sqlite3";

import { migrationStatus, openDatabase, runMigrations } from "../src/db/database.js";
import { MIGRATIONS, type Migration } from "../src/db/migrations.js";

const dirs: string[] = [];
const openHandles: Array<{ close: () => void }> = [];

function tempDir(): string {
  const dir = mkdtempSync(join(tmpdir(), "cg-db-"));
  dirs.push(dir);
  return dir;
}

afterEach(() => {
  while (openHandles.length) openHandles.pop()?.close();
  while (dirs.length) rmSync(dirs.pop() as string, { recursive: true, force: true });
});

const EXPECTED_TABLES = [
  "alerts",
  "consumer_use_fields",
  "consumer_uses",
  "consumers",
  "events",
  "findings",
  "operations",
  "schema_migrations",
  "services",
  "spec_versions",
  "wire_fields",
];

describe("openDatabase", () => {
  it("creates the parent directory and applies the baseline migration", () => {
    const target = join(tempDir(), "nested", "deeper", "contract-guard.db");
    const { db, applied } = openDatabase({ path: target });
    openHandles.push(db);

    expect(applied).toEqual(["0001_baseline_registry_schema"]);
    expect(existsSync(target)).toBe(true);
  });

  it("creates every registry table from PLAN.md §5", () => {
    const { db } = openDatabase({ path: join(tempDir(), "cg.db") });
    openHandles.push(db);

    const tables = (
      db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name").all() as Array<{
        name: string;
      }>
    ).map((row) => row.name);

    for (const table of EXPECTED_TABLES) expect(tables).toContain(table);
  });

  it("works with an in-memory database", () => {
    const { db, applied } = openDatabase({ path: ":memory:" });
    openHandles.push(db);
    expect(applied).toHaveLength(1);
    expect(migrationStatus(db).pending).toEqual([]);
  });

  it("re-running on the same file is a safe no-op", () => {
    const path = join(tempDir(), "cg.db");

    const first = openDatabase({ path });
    first.db.close();
    expect(first.applied).toEqual(["0001_baseline_registry_schema"]);

    const second = openDatabase({ path });
    openHandles.push(second.db);
    expect(second.applied).toEqual([]);
    expect(migrationStatus(second.db)).toEqual({
      applied: ["0001_baseline_registry_schema"],
      pending: [],
    });
  });

  it("keeps data across reopening the same file", () => {
    const path = join(tempDir(), "cg.db");

    const first = openDatabase({ path });
    first.db.prepare("INSERT INTO services (name, owner) VALUES (?, ?)").run("quote-api", "Quotes team");
    first.db.close();

    const second = openDatabase({ path });
    openHandles.push(second.db);
    const rows = second.db.prepare("SELECT name, owner FROM services").all() as Array<{
      name: string;
      owner: string;
    }>;
    expect(rows).toEqual([{ name: "quote-api", owner: "Quotes team" }]);
  });

  it("enables foreign keys", () => {
    const { db } = openDatabase({ path: join(tempDir(), "cg.db") });
    openHandles.push(db);
    expect(db.pragma("foreign_keys", { simple: true })).toBe(1);
    expect(() =>
      db
        .prepare("INSERT INTO spec_versions (service_id, version, status) VALUES (999, '1.0.0', 'published')")
        .run(),
    ).toThrow(/FOREIGN KEY/i);
  });
});

describe("runMigrations", () => {
  it("applies migrations in id order", () => {
    const db = new BetterSqlite3(":memory:");
    openHandles.push(db);

    const fixtures: Migration[] = [
      { id: "0002_second", description: "second", sql: "CREATE TABLE second (x INTEGER);" },
      { id: "0001_first", description: "first", sql: "CREATE TABLE first (x INTEGER);" },
    ];

    expect(runMigrations(db, fixtures)).toEqual(["0001_first", "0002_second"]);
    const names = (
      db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name").all() as Array<{
        name: string;
      }>
    ).map((row) => row.name);
    expect(names).toContain("first");
    expect(names).toContain("second");
  });

  it("rolls back a failing migration completely, leaving no partial schema or record", () => {
    const db = new BetterSqlite3(":memory:");
    openHandles.push(db);

    const broken: Migration = {
      id: "0001_broken",
      description: "creates a table then fails",
      sql: "CREATE TABLE should_not_exist (x INTEGER); SELECT * FROM table_that_is_not_real;",
    };

    expect(() => runMigrations(db, [broken])).toThrow(/migration 0001_broken .* failed/);

    const table = db
      .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'should_not_exist'")
      .get();
    expect(table).toBeUndefined();

    const recorded = db.prepare("SELECT id FROM schema_migrations WHERE id = '0001_broken'").get();
    expect(recorded).toBeUndefined();
  });

  it("skips migrations already recorded and keeps pending ones visible", () => {
    const db = new BetterSqlite3(":memory:");
    openHandles.push(db);

    // Install only the bookkeeping table, so the baseline looks pending.
    db.exec("CREATE TABLE schema_migrations (id TEXT PRIMARY KEY, applied_at TEXT)");
    const status = migrationStatus(db);
    expect(status.applied).toEqual([]);
    expect(status.pending).toEqual(MIGRATIONS.map((migration) => migration.id));

    expect(runMigrations(db, [])).toEqual([]);
    expect(migrationStatus(db).pending).toEqual(MIGRATIONS.map((migration) => migration.id));
  });

  it("ships exactly one baseline migration for Phase 0", () => {
    expect(MIGRATIONS.map((migration) => migration.id)).toEqual(["0001_baseline_registry_schema"]);
  });

  it("reserves the statuses required by locked decision L-2", () => {
    const { db } = openDatabase({ path: join(tempDir(), "cg.db") });
    openHandles.push(db);
    db.prepare("INSERT INTO services (name) VALUES ('claims-api')").run();
    const serviceId = (db.prepare("SELECT id FROM services WHERE name = 'claims-api'").get() as { id: number }).id;

    const insert = db.prepare(
      "INSERT INTO spec_versions (service_id, version, status) VALUES (?, ?, ?)",
    );
    for (const status of ["staged", "published", "blocked", "rejected", "invalid"]) {
      expect(() => insert.run(serviceId, `1.0.${status}`, status)).not.toThrow();
    }
    // A version number cannot be occupied twice for the same service.
    expect(() => insert.run(serviceId, "1.0.published", "blocked")).toThrow(/UNIQUE/i);
    expect(() => insert.run(serviceId, "9.9.9", "not_a_status")).toThrow(/CHECK/i);
  });
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import request from "supertest";

import { createApp } from "../src/app.js";
import { loadConfig } from "../src/config.js";
import { openDatabase } from "../src/db/database.js";
import { createLogger } from "../src/logger.js";

const dirs: string[] = [];
const handles: Array<{ close: () => void }> = [];

const silentLogger = createLogger({ level: "error" });

function build(overrides: NodeJS.ProcessEnv = {}) {
  const dir = mkdtempSync(join(tmpdir(), "cg-health-"));
  dirs.push(dir);
  const config = loadConfig({ CG_DB_PATH: join(dir, "cg.db"), ...overrides }, dir);
  const { db, applied } = openDatabase({ path: config.dbPath });
  handles.push(db);
  return { app: createApp({ config, db, logger: silentLogger }), config, applied };
}

afterEach(() => {
  while (handles.length) handles.pop()?.close();
  while (dirs.length) rmSync(dirs.pop() as string, { recursive: true, force: true });
});

describe("GET /api/health", () => {
  it("returns 200 with the running configuration once migrations are applied", async () => {
    const { app, applied } = build({ CG_AS_OF_DATE: "2026-11-18", GATE_MODE: "strict" });
    expect(applied).toEqual(["0001_baseline_registry_schema"]);

    const response = await request(app).get("/api/health").expect(200);

    expect(response.body).toMatchObject({
      status: "ok",
      service: "contract-guard",
      gateMode: "strict",
      asOfDate: "2026-11-18",
      asOfDatePinned: true,
      fresh: true,
      webhookUrl: "http://localhost:9900",
      db: { ok: true, migrations: ["0001_baseline_registry_schema"], pending: [] },
    });
    expect(typeof response.body.version).toBe("string");
    expect(typeof response.body.uptimeSeconds).toBe("number");
  });

  it("reports the unpinned as-of date when CG_AS_OF_DATE is absent", async () => {
    const { app, config } = build();
    const response = await request(app).get("/api/health").expect(200);
    expect(response.body.asOfDate).toBe(config.asOfDate.toISOString().slice(0, 10));
    expect(response.body.asOfDatePinned).toBe(false);
  });

  it("degrades to 503 while migrations are pending", async () => {
    const dir = mkdtempSync(join(tmpdir(), "cg-health-pending-"));
    dirs.push(dir);
    const config = loadConfig({ CG_DB_PATH: join(dir, "cg.db") }, dir);
    // Open without installing the baseline, so it stays pending.
    const { db, applied } = openDatabase({ path: config.dbPath, migrations: [] });
    handles.push(db);
    expect(applied).toEqual([]);

    const response = await request(createApp({ config, db, logger: silentLogger }))
      .get("/api/health")
      .expect(503);

    expect(response.body.status).toBe("degraded");
    expect(response.body.db.ok).toBe(false);
    expect(response.body.db.pending).toEqual(["0001_baseline_registry_schema"]);
  });

  it("serves JSON errors for unknown routes", async () => {
    const { app } = build();
    const response = await request(app).get("/api/nope").expect(404);
    expect(response.body).toEqual({ error: "not_found" });
  });
});

