/**
 * Phase 1 pipeline: discover the local kit, load and validate every file, and
 * record intake results. Later phases add the gate and notifier around this;
 * Phase 7 calls it from the startup sequence.
 */
import type { Database } from "../db/database.js";
import type { Logger } from "../logger.js";
import { discoverConsumerFiles, discoverSpecFiles, type SpecFileRef } from "../loader/discovery.js";
import { loadConsumerFile, type ConsumerIntake } from "../loader/consumerLoader.js";
import { loadSpecFile, type SpecIntake } from "../loader/specLoader.js";
import { recordIntake, type IntakeSummary } from "../registry/intakeStore.js";

export interface KitLoadResult {
  /** Spec intakes grouped by service, each service in publication order. */
  specsByService: Map<string, SpecIntake[]>;
  /** Flat list in service order, then publication order. */
  specs: SpecIntake[];
  consumers: ConsumerIntake[];
  summary: IntakeSummary;
  invalidSpecs: SpecIntake[];
}

function describe(ref: SpecFileRef): string {
  return `${ref.relativePath}`;
}

export function loadKit(kitRoot: string, db: Database, logger?: Logger): KitLoadResult {
  const log = logger;
  const grouped = discoverSpecFiles(kitRoot);

  const specsByService = new Map<string, SpecIntake[]>();
  const specs: SpecIntake[] = [];
  for (const [service, refs] of grouped) {
    const intakes = refs.map((ref) => {
      const intake = loadSpecFile(ref);
      log?.debug("spec intake", {
        file: describe(ref),
        version: intake.version,
        valid: intake.valid,
        issues: intake.issues.length,
      });
      return intake;
    });
    specsByService.set(service, intakes);
    specs.push(...intakes);
  }

  const consumerRefs = discoverConsumerFiles(kitRoot);
  const consumers = consumerRefs.map((ref) => {
    const intake = loadConsumerFile(ref);
    log?.debug("consumer intake", {
      file: ref.relativePath,
      uses: intake.uses.length,
      valid: intake.valid,
    });
    return intake;
  });

  const summary = recordIntake(db, specs, consumers);
  const invalidSpecs = specs.filter((spec) => !spec.valid);

  log?.info("kit intake complete", {
    services: new Set(specs.map((spec) => spec.service)).size,
    specVersions: specs.length,
    consumers: consumers.length,
    invalidSpecs: invalidSpecs.length,
    findings: summary.findings,
  });

  return { specsByService, specs, consumers, summary, invalidSpecs };
}

import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import {
  discoverConsumerFiles,
  discoverSpecFileList,
  discoverSpecFiles,
  publishOrderOf,
} from "../src/loader/discovery.js";

/** Repo root: contract-guard/test/ → ../../ */
const KIT_ROOT = fileURLToPath(new URL("../../", import.meta.url));

describe("publishOrderOf", () => {
  it("reads the numeric filename prefix", () => {
    expect(publishOrderOf("1-initial.yaml")).toBe(1);
    expect(publishOrderOf("3-channel-and-notes-fixed.yaml")).toBe(3);
    expect(publishOrderOf("4-approval-later.yaml")).toBe(4);
  });

  it("sorts unprefixed names last", () => {
    expect(publishOrderOf("draft.yaml")).toBe(Number.MAX_SAFE_INTEGER);
  });
});

describe("discoverSpecFiles against the real kit", () => {
  it("finds 12 spec files across 3 services in numeric order per service", () => {
    const grouped = discoverSpecFiles(KIT_ROOT);
    expect([...grouped.keys()].sort()).toEqual(["claims-api", "policy-api", "quote-api"]);

    const expected: Record<string, string[]> = {
      "quote-api": [
        "1-initial.yaml",
        "2-reorganised.yaml",
        "3-price-lines.yaml",
        "4-ncb-and-taxes.yaml",
      ],
      "policy-api": [
        "1-initial.yaml",
        "2-deprecations.yaml",
        "3-remove-old-fields.yaml",
        "4-endorsement-rules.yaml",
      ],
      "claims-api": [
        "1-initial.yaml",
        "2-channel-and-notes.yaml",
        "3-channel-and-notes-fixed.yaml",
        "4-approval-later.yaml",
      ],
    };

    for (const [service, fileNames] of Object.entries(expected)) {
      const files = grouped.get(service);
      expect(files, `missing service ${service}`).toBeDefined();
      expect(files?.map((file) => file.fileName)).toEqual(fileNames);
      expect(files?.map((file) => file.order)).toEqual([1, 2, 3, 4]);
    }

    expect(discoverSpecFileList(KIT_ROOT)).toHaveLength(12);
  });

  it("uses the folder name as the service identity that consumers reference", () => {
    for (const file of discoverSpecFileList(KIT_ROOT)) {
      expect(file.service).toBe(file.relativePath.split("/")[1]);
      expect(file.absolutePath.endsWith(file.relativePath)).toBe(true);
    }
  });
});

describe("discoverConsumerFiles against the real kit", () => {
  it("finds all four consumer manifests", () => {
    const consumers = discoverConsumerFiles(KIT_ROOT);
    expect(consumers.map((consumer) => consumer.name)).toEqual([
      "mobile-app",
      "notifications-svc",
      "partner-portal",
      "payments-svc",
    ]);
    for (const consumer of consumers) {
      expect(consumer.relativePath).toBe(`consumers/${consumer.fileName}`);
    }
  });
});

import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, describe, expect, it } from "vitest";

import { loadSpecFile } from "../src/loader/specLoader.js";
import { collectReferences, resolveLocalPointer, validateSpec } from "../src/validator/specValidator.js";
import { parseYaml } from "../src/loader/readFile.js";
import type { SpecFileRef } from "../src/loader/discovery.js";

const dirs: string[] = [];
afterAll(() => {
  for (const dir of dirs) rmSync(dir, { recursive: true, force: true });
});

/** Fixtures live in a temp directory: the kit's specs/ folder is never written. */
function fixtureRef(yamlText: string, fileName = "1-fixture.yaml"): SpecFileRef {
  const dir = mkdtempSync(join(tmpdir(), "cg-spec-fixture-"));
  dirs.push(dir);
  const absolutePath = join(dir, fileName);
  writeFileSync(absolutePath, yamlText, "utf8");
  return {
    service: "fixture-api",
    order: 1,
    fileName,
    relativePath: `fixtures/${fileName}`,
    absolutePath,
  };
}

const VALID_SPEC = `
openapi: 3.0.3
info:
  title: Fixture API
  version: 1.0.0
  description: 'Fixtures. Owner: Fixture team.'
paths:
  /things:
    get:
      operationId: listThings
      responses:
        '200':
          description: list
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/Thing'
components:
  schemas:
    Thing:
      type: object
      required: [id]
      properties:
        id:
          type: string
`;

describe("validateSpec on a sound document", () => {
  it("reports no issues", () => {
    const parsed = parseYaml(VALID_SPEC);
    expect(parsed.ok).toBe(true);
    expect(validateSpec(parsed.value)).toEqual([]);
  });

  it("collects internal references and resolves them", () => {
    const parsed = parseYaml(VALID_SPEC) as { value: unknown };
    const references = collectReferences(parsed.value);
    expect(references).toHaveLength(1);
    expect(references[0]?.ref).toBe("#/components/schemas/Thing");
    expect(resolveLocalPointer(parsed.value, "#/components/schemas/Thing").ok).toBe(true);
    expect(resolveLocalPointer(parsed.value, "#/components/schemas/Nope").ok).toBe(false);
  });
});

describe("validateSpec rejects broken documents", () => {
  it("flags a dangling $ref by name", () => {
    const yamlText = VALID_SPEC.replace(
      "$ref: '#/components/schemas/Thing'",
      "$ref: '#/components/schemas/Thinggg'",
    );
    const intake = loadSpecFile(fixtureRef(yamlText));
    expect(intake.valid).toBe(false);
    expect(intake.issues.map((issue) => issue.code)).toContain("ERR_INVALID_SPEC");
    expect(intake.issues[0]?.message).toMatch(/unresolved \$ref "#\/components\/schemas\/Thinggg"/);
    expect(intake.issues[0]?.severity).toBe("blocking");
    // Metadata is still recorded so the version can be reserved (L-2).
    expect(intake.version).toBe("1.0.0");
  });

  it("flags an external $ref, which the kit never uses", () => {
    const yamlText = VALID_SPEC.replace(
      "$ref: '#/components/schemas/Thing'",
      "$ref: 'other-file.yaml#/components/schemas/Thing'",
    );
    const issues = validateSpec((parseYaml(yamlText) as { value: unknown }).value);
    expect(issues.map((issue) => issue.message).join(" ")).toMatch(/external \$ref/);
  });

  it("flags duplicate operationIds", () => {
    const yamlText = `
openapi: 3.0.3
info: { title: Fixture, version: 1.0.0 }
paths:
  /a:
    get:
      operationId: sameName
      responses: { '204': { description: ok } }
  /b:
    get:
      operationId: sameName
      responses: { '204': { description: ok } }
`;
    const issues = validateSpec((parseYaml(yamlText) as { value: unknown }).value);
    expect(issues.map((issue) => issue.message).join(" ")).toMatch(
      /operationId "sameName" is declared 2 times/,
    );
  });

  it("flags two path templates that collide once parameters are normalized", () => {
    const yamlText = `
openapi: 3.0.3
info: { title: Fixture, version: 1.0.0 }
paths:
  /things/{id}:
    get:
      operationId: getOne
      responses: { '204': { description: ok } }
  /things/{thingId}:
    get:
      operationId: getOther
      responses: { '204': { description: ok } }
`;
    const issues = validateSpec((parseYaml(yamlText) as { value: unknown }).value);
    expect(issues.map((issue) => issue.message).join(" ")).toMatch(/GET \/things\/\{\} is declared more than once/);
  });

  it("flags a missing info.version", () => {
    const yamlText = `
openapi: 3.0.3
info: { title: Fixture }
paths:
  /a:
    get: { operationId: a, responses: { '204': { description: ok } } }
`;
    const issues = validateSpec((parseYaml(yamlText) as { value: unknown }).value);
    expect(issues.map((issue) => issue.message)).toContain("spec has no usable `info.version`");
  });

  it("flags a spec with no operations", () => {
    const yamlText = `
openapi: 3.0.3
info: { title: Fixture, version: 1.0.0 }
paths: {}
`;
    const issues = validateSpec((parseYaml(yamlText) as { value: unknown }).value);
    expect(issues.map((issue) => issue.message)).toContain("spec declares no operations under `paths`");
  });
});

describe("loadSpecFile never throws on malformed input", () => {
  it("handles unparseable YAML", () => {
    const intake = loadSpecFile(fixtureRef("openapi: 3.0.3\ninfo: [unclosed\n"));
    expect(intake.valid).toBe(false);
    expect(intake.issues[0]?.code).toBe("ERR_INVALID_SPEC");
    expect(intake.issues[0]?.message).toMatch(/YAML parse error/);
    expect(intake.contentHash).toMatch(/^[0-9a-f]{64}$/);
  });

  it("handles a document that is not a mapping", () => {
    const intake = loadSpecFile(fixtureRef("- just\n- a\n- list\n"));
    expect(intake.valid).toBe(false);
    expect(intake.issues[0]?.message).toBe("spec is not a YAML mapping");
  });

  it("handles a file that cannot be read", () => {
    const intake = loadSpecFile({
      service: "fixture-api",
      order: 1,
      fileName: "missing.yaml",
      relativePath: "fixtures/missing.yaml",
      absolutePath: join(mkdtempSync(join(tmpdir(), "cg-missing-")), "does-not-exist.yaml"),
    });
    expect(intake.valid).toBe(false);
    expect(intake.issues[0]?.message).toMatch(/could not read file/);
  });

  it("records version, title and owner for a valid spec", () => {
    const intake = loadSpecFile(fixtureRef(VALID_SPEC));
    expect(intake.valid).toBe(true);
    expect(intake.version).toBe("1.0.0");
    expect(intake.title).toBe("Fixture API");
    expect(intake.owner).toBe("Fixture team");
  });
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";

import { openDatabase, type Database } from "../src/db/database.js";
import { loadKit } from "../src/pipeline/loadKit.js";
import { kitFingerprint } from "../src/loader/fingerprint.js";

const KIT_ROOT = fileURLToPath(new URL("../../", import.meta.url));
/** Recorded baseline for the untouched starter kit (Phase 0 report). */
const KIT_BASELINE_DIGEST = "6a6b6988254f79a3e1d7a6c37fcf994c67bad4278f14c1a03371dbde7792cd87";

const dirs: string[] = [];
const handles: Array<Database> = [];
afterEach(() => {
  while (handles.length) handles.pop()?.close();
  while (dirs.length) rmSync(dirs.pop() as string, { recursive: true, force: true });
});

function freshDb(): Database {
  const dir = mkdtempSync(join(tmpdir(), "cg-intake-"));
  dirs.push(dir);
  const { db } = openDatabase({ path: join(dir, "cg.db") });
  handles.push(db);
  return db;
}

function count(db: Database, table: string): number {
  return (db.prepare(`SELECT COUNT(*) AS n FROM ${table}`).get() as { n: number }).n;
}

describe("loadKit reads the whole starter kit", () => {
  it("loads all 12 spec files and 4 consumers, versions taken from info.version", () => {
    const db = freshDb();
    const result = loadKit(KIT_ROOT, db);

    expect(result.specs).toHaveLength(12);
    expect(result.consumers).toHaveLength(4);

    const versionsByService = new Map<string, string[]>();
    for (const [service, intakes] of result.specsByService) {
      versionsByService.set(service, intakes.map((intake) => intake.version));
    }
    expect(versionsByService.get("quote-api")).toEqual(["1.0.0", "1.1.0", "2.0.0", "2.1.0"]);
    expect(versionsByService.get("policy-api")).toEqual(["1.0.0", "1.1.0", "2.0.0", "2.1.0"]);
    // Two files both declare 1.1.0: the corrected re-publication collides (L-2).
    expect(versionsByService.get("claims-api")).toEqual(["1.0.0", "1.1.0", "1.1.0", "2.0.0"]);

    const owners = new Map(
      [...result.specsByService.entries()].map(([service, intakes]) => [service, intakes[0]?.owner]),
    );
    expect(owners.get("quote-api")).toBe("Quotes team");
    expect(owners.get("policy-api")).toBe("Policy team");
    expect(owners.get("claims-api")).toBe("Claims team");
  });

  it("records intake rows in the registry tables", () => {
    const db = freshDb();
    const result = loadKit(KIT_ROOT, db);

    expect(count(db, "services")).toBe(3);
    expect(count(db, "spec_versions")).toBe(12);
    expect(count(db, "consumers")).toBe(4);

    const statuses = db.prepare("SELECT DISTINCT status FROM spec_versions").all() as Array<{
      status: string;
    }>;
    expect(statuses.map((row) => row.status)).toEqual(["staged"]);

    expect(result.summary.consumerUses).toBe(10);
    expect(result.summary.consumerUseFields).toBe(50);
    expect(count(db, "consumer_uses")).toBe(10);
    expect(count(db, "consumer_use_fields")).toBe(50);
  });

  it("re-running intake is idempotent so L-3 replays cannot duplicate rows", () => {
    const db = freshDb();
    loadKit(KIT_ROOT, db);
    const second = loadKit(KIT_ROOT, db);

    expect(count(db, "spec_versions")).toBe(12);
    expect(count(db, "consumers")).toBe(4);
    expect(count(db, "consumer_uses")).toBe(10);
    expect(count(db, "consumer_use_fields")).toBe(50);
    expect(count(db, "findings")).toBe(second.summary.findings);
  });
});

describe("validation against the kit's planted broken spec", () => {
  it("reports claims-api ClaimDocumnt as ERR_INVALID_SPEC without crashing", () => {
    const db = freshDb();
    const result = loadKit(KIT_ROOT, db);

    const claims = result.specsByService.get("claims-api") as NonNullable<
      ReturnType<typeof result.specsByService.get>
    >;
    const broken = claims.find((spec) => spec.fileName === "2-channel-and-notes.yaml");
    expect(broken).toBeDefined();
    expect(broken?.valid).toBe(false);
    expect(broken?.version).toBe("1.1.0");
    expect(broken?.issues.map((issue) => issue.code)).toEqual(["ERR_INVALID_SPEC"]);
    expect(broken?.issues[0]?.message).toMatch(/ClaimDocumnt/);

    expect(result.invalidSpecs.map((spec) => spec.fileName)).toEqual(["2-channel-and-notes.yaml"]);
  });

  it("accepts the corrected reference in 3-channel-and-notes-fixed.yaml", () => {
    const db = freshDb();
    const result = loadKit(KIT_ROOT, db);
    const claims = result.specsByService.get("claims-api") as never as Array<{
      fileName: string;
      valid: boolean;
      version: string;
    }>;

    const fixed = claims.find((spec) => spec.fileName === "3-channel-and-notes-fixed.yaml");
    expect(fixed).toBeDefined();
    expect(fixed?.valid).toBe(true);
    expect(fixed?.issues).toEqual([]);
    expect(fixed?.version).toBe("1.1.0");
  });

  it("considers the other ten specs structurally valid", () => {
    const db = freshDb();
    const result = loadKit(KIT_ROOT, db);
    const invalid = result.specs.filter((spec) => !spec.valid);
    expect(invalid).toHaveLength(1);
  });

  it("stores the invalid-spec finding against the right registry row", () => {
    const db = freshDb();
    loadKit(KIT_ROOT, db);

    const rows = db
      .prepare(
        `SELECT sv.source_file, sv.version, f.code, f.severity, f.message
         FROM findings f
         JOIN spec_versions sv ON sv.id = f.spec_version_id`,
      )
      .all() as Array<{ source_file: string; version: string; code: string; severity: string; message: string }>;

    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      source_file: "specs/claims-api/2-channel-and-notes.yaml",
      version: "1.1.0",
      code: "ERR_INVALID_SPEC",
      severity: "blocking",
    });
  });
});

describe("consumer manifests are indexed", () => {
  it("captures every team, call and field path", () => {
    const db = freshDb();
    const result = loadKit(KIT_ROOT, db);

    const byName = new Map(result.consumers.map((consumer) => [consumer.name, consumer]));
    expect([...byName.keys()].sort()).toEqual([
      "mobile-app",
      "notifications-svc",
      "partner-portal",
      "payments-svc",
    ]);
    expect(byName.get("mobile-app")?.team).toBe("Mobile");
    expect(byName.get("partner-portal")?.team).toBe("Partner Integrations");
    expect(byName.get("payments-svc")?.team).toBe("Payments");
    expect(byName.get("notifications-svc")?.team).toBe("Notifications");

    expect(byName.get("mobile-app")?.uses).toHaveLength(4);
    expect(byName.get("partner-portal")?.uses).toHaveLength(2);
    expect(byName.get("payments-svc")?.uses).toHaveLength(1);
    expect(byName.get("notifications-svc")?.uses).toHaveLength(3);
    for (const consumer of result.consumers) expect(consumer.valid).toBe(true);

    // Paths are stored exactly as the manifest wrote them, plus the normalized form.
    const mobileQuoteGet = byName.get("mobile-app")?.uses.find((use) => use.method === "GET");
    expect(mobileQuoteGet?.pathTemplate).toBe("/quotes/{id}");
    expect(mobileQuoteGet?.normalizedPath).toBe("/quotes/{}");

    const mobileQuotePost = byName.get("mobile-app")?.uses.find(
      (use) => use.method === "POST" && use.provider === "quote-api",
    );
    expect(mobileQuotePost?.reads).toContain("premium.breakdown[].amount");
    expect(mobileQuotePost?.sends).toEqual(["vehicle.make", "vehicle.cc", "rider.age"]);

    expect(byName.get("payments-svc")?.uses[0]?.reads).toContain("legacyCode");

    const partnerEndorsement = byName
      .get("partner-portal")
      ?.uses.find((use) => use.pathTemplate.includes("endorsements"));
    expect(partnerEndorsement?.sends).toEqual(["policyId", "type", "details"]);
    expect(partnerEndorsement?.sends).not.toContain("requestedBy");
  });
});

describe("the kit stays read-only", () => {
  it("leaves specs/ and consumers/ byte-identical after a full intake", () => {
    const before = kitFingerprint(KIT_ROOT);
    expect(before.fileCount).toBe(16);
    expect(before.digest).toBe(KIT_BASELINE_DIGEST);

    const db = freshDb();
    loadKit(KIT_ROOT, db);

    const after = kitFingerprint(KIT_ROOT);
    expect(after.digest).toBe(before.digest);
    expect(after.digest).toBe(KIT_BASELINE_DIGEST);
  });
});

