/**
 * Path-template parameters and rename aliases (locked decision D-3).
 *
 * `/quotes/{id}` and `/quotes/{quoteId}` are the same wire path, so a parameter
 * rename is a refactor, not a breaking change. Consumers were written against
 * the older names, so resolution applies a positional alias map derived from
 * the two templates: `{id}` in one, `{quoteId}` in the other, same position.
 */

const PARAM_IN_BRACES = /\{([^}]*)\}/g;

/** Ordered parameter names of a path template: `/quotes/{quoteId}` → `["quoteId"]`. */
export function templateParams(pathTemplate: string): string[] {
  return [...pathTemplate.matchAll(PARAM_IN_BRACES)].map((match) => match[1] as string);
}

/**
 * Positional rename map from one template to another. Only names that differ
 * are recorded; templates with a different number of parameters yield an empty
 * map because they are not the same wire path.
 */
export function buildParamAliasMap(fromTemplate: string, toTemplate: string): Record<string, string> {
  const from = templateParams(fromTemplate);
  const to = templateParams(toTemplate);
  if (from.length !== to.length) return {};

  const aliases: Record<string, string> = {};
  from.forEach((name, index) => {
    const target = to[index];
    if (target !== undefined && target !== name) aliases[name] = target;
  });
  return aliases;
}

/** Rewrite the first segment of a field path when it names a renamed parameter. */
export function applyParamAlias(fieldPath: string, aliases: Record<string, string>): string {
  const [head, ...rest] = fieldPath.split(".");
  if (head === undefined) return fieldPath;
  // Strip any `[]` suffix from the head segment before lookup.
  const bare = head.replace(/\[\]$/, "");
  const suffix = head.slice(bare.length);
  const mapped = aliases[bare];
  return [mapped === undefined ? head : `${mapped}${suffix}`, ...rest].join(".");
}

/** True when the templates address the same wire path, regardless of names. */
export function sameWirePath(left: string, right: string): boolean {
  return left.replace(PARAM_IN_BRACES, "{}") === right.replace(PARAM_IN_BRACES, "{}");
}

/**
 * Build the wire index for one specification version: every operation with its
 * normalized path, internal flag, request fields (parameters plus request body)
 * and response fields per status code. Field paths use consumer notation, so a
 * consumer's `sends`/`reads` entry can be looked up directly (PLAN.md §5).
 */
import { HTTP_METHOD_SET, isPlainObject } from "../domain/openapi.js";
import { normalizePathTemplate } from "../domain/paths.js";
import { flattenSchema, type WireDirection, type WireField } from "./schemaWalker.js";

export interface IndexedParameter {
  name: string;
  in: string;
  required: boolean;
  type: string | null;
}

export interface IndexedOperation {
  method: string;
  pathTemplate: string;
  normalizedPath: string;
  operationId: string | null;
  summary: string | null;
  /** `x-internal: true` — excluded from consumer-impact checks (locked PO-1). */
  isInternal: boolean;
  parameters: IndexedParameter[];
  /** Request direction fields: parameters first, then request-body fields. */
  requestFields: WireField[];
  /** Response direction fields, grouped by status code. */
  responseFieldsByStatus: Array<{ statusCode: string; fields: WireField[] }>;
}

const JSON_CONTENT_TYPE = "application/json";

function collectParameters(
  pathItem: Record<string, unknown>,
  operation: Record<string, unknown>,
): IndexedParameter[] {
  const collected: IndexedParameter[] = [];
  const sources: unknown[] = [];
  if (Array.isArray(pathItem.parameters)) sources.push(...pathItem.parameters);
  if (Array.isArray(operation.parameters)) sources.push(...operation.parameters);

  for (const entry of sources) {
    if (!isPlainObject(entry) || typeof entry.name !== "string") continue;
    const location = typeof entry.in === "string" ? entry.in : "";
    const schema = isPlainObject(entry.schema) ? entry.schema : {};
    collected.push({
      name: entry.name,
      in: location,
      // Path parameters are required by the OpenAPI spec itself.
      required: entry.required === true || location === "path",
      type: typeof schema.type === "string" ? schema.type : null,
    });
  }
  return collected;
}

function parameterField(parameter: IndexedParameter): WireField {
  return {
    path: parameter.name,
    direction: "request",
    statusCode: null,
    type: parameter.type,
    format: null,
    required: parameter.required,
    enumValues: null,
    deprecated: false,
    sunsetDate: null,
  };
}

function jsonSchemaOf(container: unknown): unknown {
  if (!isPlainObject(container)) return undefined;
  const content = isPlainObject(container.content) ? container.content : undefined;
  const media = content?.[JSON_CONTENT_TYPE];
  if (!isPlainObject(media)) return undefined;
  return media.schema;
}

function requestFields(
  document: unknown,
  parameters: IndexedParameter[],
  operation: Record<string, unknown>,
): WireField[] {
  const fields: WireField[] = [];
  const seen = new Set<string>();

  for (const parameter of parameters) {
    if (seen.has(parameter.name)) continue;
    seen.add(parameter.name);
    fields.push(parameterField(parameter));
  }

  const bodySchema = jsonSchemaOf(operation.requestBody);
  if (bodySchema !== undefined) {
    for (const field of flattenSchema(document, bodySchema, { direction: "request" })) {
      if (field.path === "" || seen.has(field.path)) continue;
      seen.add(field.path);
      fields.push(field);
    }
  }
  return fields;
}

function responseFieldsByStatus(
  document: unknown,
  operation: Record<string, unknown>,
): Array<{ statusCode: string; fields: WireField[] }> {
  const responses = isPlainObject(operation.responses) ? operation.responses : {};
  const grouped: Array<{ statusCode: string; fields: WireField[] }> = [];

  for (const [statusCode, response] of Object.entries(responses)) {
    const schema = jsonSchemaOf(response);
    if (schema === undefined) continue;
    const fields = flattenSchema(document, schema, {
      direction: "response",
      statusCode,
    }).filter((field) => field.path !== "");
    if (fields.length > 0) grouped.push({ statusCode, fields });
  }
  return grouped;
}

/** Index every operation in a specification document. Never throws. */
export function indexOperations(document: unknown): IndexedOperation[] {
  if (!isPlainObject(document)) return [];
  const paths = isPlainObject(document.paths) ? document.paths : {};
  const indexed: IndexedOperation[] = [];

  for (const [pathTemplate, pathItem] of Object.entries(paths)) {
    if (!isPlainObject(pathItem)) continue;

    for (const [key, value] of Object.entries(pathItem)) {
      if (!HTTP_METHOD_SET.has(key.toLowerCase()) || !isPlainObject(value)) continue;
      const operation = value;
      const parameters = collectParameters(pathItem, operation);

      indexed.push({
        method: key.toUpperCase(),
        pathTemplate,
        normalizedPath: normalizePathTemplate(pathTemplate),
        operationId: typeof operation.operationId === "string" ? operation.operationId : null,
        summary: typeof operation.summary === "string" ? operation.summary : null,
        isInternal: operation["x-internal"] === true,
        parameters,
        requestFields: requestFields(document, parameters, operation),
        responseFieldsByStatus: responseFieldsByStatus(document, operation),
      });
    }
  }
  return indexed;
}

/** All fields of an operation, request and response together. */
export function allFields(operation: IndexedOperation): WireField[] {
  return [
    ...operation.requestFields,
    ...operation.responseFieldsByStatus.flatMap((group) => group.fields),
  ];
}

export function fieldCount(operation: IndexedOperation): number {
  return allFields(operation).length;
}

/**
 * Comparable view of an index: sorted field keys per operation, addressed by
 * method and normalized path only. Renamed components never appear, and path
 * parameter names are excluded from the request side because the wire path —
 * not the name — is what consumers actually address (D-2, D-3).
 */
export function comparableIndex(operations: IndexedOperation[]): string[] {
  return operations
    .map((operation) => {
      const requestPaths = operation.requestFields
        .filter((field) => !operation.parameters.some((parameter) => parameter.name === field.path))
        .map((field) => wireKey(field));
      const responses = operation.responseFieldsByStatus
        .flatMap((group) => group.fields.map((field) => wireKey(field)))
        .sort();
      return [
        `${operation.method} ${operation.normalizedPath}`,
        `internal=${operation.isInternal}`,
        `params=${operation.parameters
          .map((parameter) => `${parameter.in}:${parameter.type ?? "-"}:${parameter.required ? "required" : "optional"}`)
          .sort()
          .join(",")}`,
        `request=${requestPaths.sort().join(",")}`,
        `response=${responses.join(",")}`,
      ].join(" | ");
    })
    .sort();
}

function wireKey(field: WireField): string {
  return [
    field.direction,
    field.statusCode ?? "-",
    field.path,
    field.type ?? "opaque",
    field.format ?? "-",
    field.required ? "required" : "optional",
    field.enumValues ? field.enumValues.join("|") : "-",
    field.deprecated ? "deprecated" : "-",
    field.sunsetDate ?? "-",
  ].join(":");
}

export type { WireDirection };

/**
 * Persist the wire index for a spec version (PLAN.md §5: `operations` and
 * `wire_fields`). Re-indexing replaces the previous rows for that version, so a
 * startup replay under L-3 never accumulates duplicates.
 */
import type { Database } from "../db/database.js";
import type { IndexedOperation } from "../wire/operationIndex.js";
import type { WireField } from "../wire/schemaWalker.js";

export interface WireIndexSummary {
  operations: number;
  fields: number;
}

function insertFields(db: Database, operationId: number, fields: WireField[]): number {
  const insert = db.prepare(
    `INSERT INTO wire_fields
       (operation_id, direction, status_code, field_path, type, format, required, enum_values, deprecated, sunset_date)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  );
  let count = 0;
  for (const field of fields) {
    insert.run(
      operationId,
      field.direction,
      field.statusCode,
      field.path,
      field.type,
      field.format,
      field.required ? 1 : 0,
      field.enumValues === null ? null : JSON.stringify(field.enumValues),
      field.deprecated ? 1 : 0,
      field.sunsetDate,
    );
    count += 1;
  }
  return count;
}

export function recordWireIndex(
  db: Database,
  specVersionId: number,
  operations: IndexedOperation[],
): WireIndexSummary {
  const summary: WireIndexSummary = { operations: 0, fields: 0 };

  const write = db.transaction(() => {
    const existing = db
      .prepare("SELECT id FROM operations WHERE spec_version_id = ?")
      .all(specVersionId) as Array<{ id: number }>;
    for (const row of existing) {
      db.prepare("DELETE FROM wire_fields WHERE operation_id = ?").run(row.id);
    }
    db.prepare("DELETE FROM operations WHERE spec_version_id = ?").run(specVersionId);

    const insertOperation = db.prepare(
      `INSERT INTO operations (spec_version_id, method, path_template, normalized_path, operation_id, summary, is_internal)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
    );

    for (const operation of operations) {
      const result = insertOperation.run(
        specVersionId,
        operation.method,
        operation.pathTemplate,
        operation.normalizedPath,
        operation.operationId,
        operation.summary,
        operation.isInternal ? 1 : 0,
      );
      const operationId = Number(result.lastInsertRowid);
      summary.operations += 1;
      summary.fields += insertFields(
        db,
        operationId,
        allOperationFields(operation),
      );
    }
  });

  write();
  return summary;
}

/** Request fields plus every response group, in the shape `wire_fields` stores. */
function allOperationFields(operation: IndexedOperation): WireField[] {
  return [...operation.requestFields, ...operation.responseFieldsByStatus.flatMap((g) => g.fields)];
}

/**
 * Consumer index: the stored `consumer_uses` rows plus the machinery that
 * resolves a manifest against a service's wire index. Matching is by method and
 * normalized path, and the manifest's field paths are rewritten through the
 * positional parameter-alias map, so a manifest written against `/quotes/{id}`
 * still resolves against a spec that renamed it to `/quotes/{quoteId}` (D-3).
 */
import type { Database } from "../db/database.js";
import type { IndexedOperation } from "../wire/operationIndex.js";
import { applyParamAlias, buildParamAliasMap } from "../wire/aliases.js";

export interface ConsumerUseIndex {
  useId: number;
  consumer: string;
  team: string | null;
  provider: string;
  method: string;
  pathTemplate: string;
  normalizedPath: string;
  sends: string[];
  reads: string[];
}

export interface ResolvedUse {
  use: ConsumerUseIndex;
  /** The operation the manifest addresses, or `undefined` when the provider has none. */
  operation: IndexedOperation | undefined;
  /** Parameter renames between the manifest template and the operation template. */
  aliasMap: Record<string, string>;
  /** Manifest `sends` after alias rewriting, in the operation's own names. */
  resolvedSends: string[];
  /** Manifest `reads` after alias rewriting. */
  resolvedReads: string[];
}

export function loadConsumerIndex(db: Database): ConsumerUseIndex[] {
  const uses = db
    .prepare(
      `SELECT cu.id AS use_id, c.name AS consumer, c.team AS team,
              cu.provider AS provider, cu.method AS method,
              cu.path_template AS path_template, cu.normalized_path AS normalized_path
       FROM consumer_uses cu
       JOIN consumers c ON c.id = cu.consumer_id
       ORDER BY c.name, cu.provider, cu.method, cu.path_template`,
    )
    .all() as Array<{
    use_id: number;
    consumer: string;
    team: string | null;
    provider: string;
    method: string;
    path_template: string;
    normalized_path: string;
  }>;

  const fields = db.prepare(
    "SELECT use_id, direction, field_path FROM consumer_use_fields ORDER BY id",
  ).all() as Array<{ use_id: number; direction: "sends" | "reads"; field_path: string }>;

  const byUse = new Map<number, { sends: string[]; reads: string[] }>();
  for (const row of fields) {
    const bucket = byUse.get(row.use_id) ?? { sends: [], reads: [] };
    bucket[row.direction].push(row.field_path);
    byUse.set(row.use_id, bucket);
  }

  return uses.map((row) => ({
    useId: row.use_id,
    consumer: row.consumer,
    team: row.team,
    provider: row.provider,
    method: row.method,
    pathTemplate: row.path_template,
    normalizedPath: row.normalized_path,
    sends: byUse.get(row.use_id)?.sends ?? [],
    reads: byUse.get(row.use_id)?.reads ?? [],
  }));
}

/** Same wire path and method — parameter names are irrelevant (D-3). */
export function matchesOperation(
  use: Pick<ConsumerUseIndex, "method" | "normalizedPath">,
  operation: Pick<IndexedOperation, "method" | "normalizedPath">,
): boolean {
  return use.method === operation.method && use.normalizedPath === operation.normalizedPath;
}

export function findOperationForUse(
  use: Pick<ConsumerUseIndex, "method" | "normalizedPath">,
  operations: IndexedOperation[],
): IndexedOperation | undefined {
  return operations.find((operation) => matchesOperation(use, operation));
}

/** Resolve one manifest entry against one service's operations. */
export function resolveUse(use: ConsumerUseIndex, operations: IndexedOperation[]): ResolvedUse {
  const operation = findOperationForUse(use, operations);
  const aliasMap =
    operation === undefined
      ? {}
      : buildParamAliasMap(use.pathTemplate, operation.pathTemplate);

  const rewrite = (paths: string[]): string[] =>
    paths.map((path) => applyParamAlias(path, aliasMap));

  return {
    use,
    operation,
    aliasMap,
    resolvedSends: rewrite(use.sends),
    resolvedReads: rewrite(use.reads),
  };
}

/** Resolve every indexed manifest entry against the given operations per provider. */
export function resolveConsumerIndex(
  index: ConsumerUseIndex[],
  operationsByProvider: Map<string, IndexedOperation[]>,
): ResolvedUse[] {
  return index.map((use) => resolveUse(use, operationsByProvider.get(use.provider) ?? []));
}

/** Operations grouped by provider service name, for consumer resolution. */
export function groupOperationsByProvider(
  operationsByService: Map<string, IndexedOperation[]>,
): Map<string, IndexedOperation[]> {
  return new Map(operationsByService);
}

