export function diffWireIndexes(baselineOps, candidateOps, options): WireDiffResult {
  const findings: Finding[] = [];
  const aliases: OperationAlias[] = [];

  const baselineByKey = new Map(baselineOps.map(op => [opKey(op.method, op.normalizedPath), op]));
  const candidateByKey = new Map(...);

  for (const [key, base] of baselineByKey) {
    const cand = candidateByKey.get(key);
    if (cand === undefined) {
      if (base.isInternal) findings.push(finding("WARN_INTERNAL_CHANGE_NOTED", `operation ${key} removed — x-internal, excluded from the gate`, {operationRef:key}));
      else findings.push(finding("ERR_BREAKING_OPERATION_REMOVED", `${key} no longer exists`, {operationRef:key}));
      continue;
    }
    const aliasMap = buildParamAliasMap(base.pathTemplate, cand.pathTemplate);
    if (Object.keys(aliasMap).length > 0) aliases.push({method, normalizedPath, baselinePath: base.pathTemplate, candidatePath: cand.pathTemplate, aliasMap});
    diffRequest(base, cand, aliasMap, options, findings);
    diffResponse(base, cand, options, findings);
  }
  // added operations: new optional fields, no findings; new required request fields inside a brand new operation cannot break existing consumers
  sortFindings(findings);
  return { findings, aliases };
}
```

