```ts
import { applyParamAlias, buildParamAliasMap } from "../wire/aliases.js";

export interface ParamAliasRecord {
  operationRef: string;
  baselinePath: string;
  candidatePath: string;
  aliasMap: Record<string, string>;
}

export function collectParamAliases(baseline, candidate): ParamAliasRecord[] {
  const candidateByKey = new Map(...);
  const records = [];
  for (const before of baseline) {
    const after = candidateByKey.get(operationKey(before));
    if (!after) continue;
    const aliasMap = buildParamAliasMap(before.pathTemplate, after.pathTemplate);
    if (Object.keys(aliasMap).length) records.push({operationRef: operationRef(after.method, after.pathTemplate), baselinePath: before.pathTemplate, candidatePath: after.pathTemplate, aliasMap});
  }
  return records;
}
```

In diffOperation, rewrite the baseline request field keys:

```ts
function fieldMapOf(before: IndexedOperation, aliasMap: Record<string,string>) {
  const paramNames = new Set(before.parameters.map(p => p.name));
  for request field: key = paramNames.has(field.path) ? applyParamAlias(field.path, aliasMap) : field.path
}
```

fieldMapOf is used for both before (with alias) and after (identity). Refactor: fieldMapOf(operation, aliasMap = {}).

