/**
 * Consumer impact engine (PLAN.md §5). It takes the diff findings of one
 * candidate publication and attributes them to the consumers that actually
 * break, matching each `consumer_use` by (provider, method, normalized path)
 * and checking the manifest's `sends`/`reads` field paths — alias-rewritten
 * through the parameter map (D-3) — against the operation's wire fields.
 *
 * Locked rules applied here:
 * - PO-1/L-1: `x-internal` operations are skipped entirely.
 * - Rulebook: a request field added as `required` breaks consumers that do
 *   NOT send it; removed/relaxed fields break the consumers that DO send/read
 *   them.
 * - L-5: a manifest that names an enum field without listing values gets the
 *   conservative verdict when an enum option is removed — reported as a
 *   possible-usage match, with wording that says so.
 */

import type { Finding, FindingCode, FindingSeverity } from "../findings/codes.js";
import type { IndexedOperation } from "../wire/operationIndex.js";
import { resolveUse, type ConsumerUseIndex } from "../consumers/consumerIndex.js";
import { normalizePathTemplate } from "../domain/paths.js";

export interface ConsumerImpact {
  consumer: string;
  team: string | null;
  /** `consumer_uses.id` of the manifest entry that is affected. */
  useId: number;
  provider: string;
  method: string;
  /** Path template as the manifest wrote it (e.g. `/quotes/{id}`). */
  pathTemplate: string;
  /** Which side of the manifest the field lives on. */
  direction: "sends" | "reads";
  /** Same code as the underlying diff finding. */
  code: FindingCode;
  severity: FindingSeverity;
  /** Candidate-side field path, or `null` for whole-operation findings. */
  fieldPath: string | null;
  /** Manifest field path that matched, alias-rewritten to the candidate's names. */
  matchedField: string | null;
  operationRef: string;
  message: string;
  /** True for the L-5 conservative enum verdict. */
  possibleUsage: boolean;
}

export interface ImpactInput {
  /** Provider service name these findings concern, e.g. `quote-api`. */
  service: string;
  /** Findings the diff engine produced for this candidate. */
  findings: Finding[];
  /** Operations of the candidate's baseline (last published) version. */
  baselineOperations: IndexedOperation[];
  /** Operations of the candidate version. */
  candidateOperations: IndexedOperation[];
  /** The full consumer index; entries for other providers are ignored. */
  consumerIndex: ConsumerUseIndex[];
}

interface OperationRefParts {
  method: string;
  normalizedPath: string;
}

/** Parse a finding's `operationRef` back into a lookup key. */
function parseOperationRef(operationRef: string): OperationRefParts {
  const space = operationRef.indexOf(" ");
  const method = operationRef.slice(0, space).toUpperCase();
  const template = operationRef.slice(space + 1);
  return { method, normalizedPath: normalizePathTemplate(template) };
}

function operationKey(method: string, normalizedPath: string): string {
  return `${method} ${normalizedPath}`;
}

function operationAt(
  operations: IndexedOperation[],
  ref: OperationRefParts,
): IndexedOperation | undefined {
  return operations.find(
    (operation) => operationKey(operation.method, operation.normalizedPath) === operationKey(ref.method, ref.normalizedPath),
  );
}

interface FieldSides {
  request: boolean;
  response: boolean;
}

function fieldSidesOf(
  baseline: IndexedOperation | undefined,
  candidate: IndexedOperation | undefined,
  fieldPath: string,
): FieldSides {
  const sides: FieldSides = { request: false, response: false };
  for (const operation of [baseline, candidate]) {
    if (operation === undefined) continue;
    if (operation.requestFields.some((field) => field.path === fieldPath)) sides.request = true;
    if (
      operation.responseFieldsByStatus.some((group) =>
        group.fields.some((field) => field.path === fieldPath),
      )
    ) {
      sides.response = true;
    }
  }
  return sides;
}

function isBlockingCode(code: FindingCode): boolean {
  return code.startsWith("ERR_");
}

/**
 * Attribute findings to consumers. Only blocking (`ERR_`) findings can create
 * consumer impact; warnings and notes are recorded for the dashboard and the
 * gate's unconsumed-breaking logic, never as a consumer break.
 */
export function attributeConsumerImpacts(input: ImpactInput): ConsumerImpact[] {
  const { service, findings, baselineOperations, candidateOperations } = input;

  // Resolve only this provider's manifest entries against this candidate.
  const resolved = input.consumerIndex
    .filter((use) => use.provider === service)
    .map((use) => resolveUse(use, candidateOperations));

  const impacts: ConsumerImpact[] = [];

  for (const item of findings) {
    if (item.operationRef === undefined || !isBlockingCode(item.code)) continue;

    const ref = parseOperationRef(item.operationRef);
    const baselineOp = operationAt(baselineOperations, ref);
    const candidateOp = operationAt(candidateOperations, ref);

    // PO-1/L-1: internal operations skip consumer-impact checks entirely.
    if (candidateOp?.isInternal === true || baselineOp?.isInternal === true) continue;

    for (const entry of resolved) {
      const { use, resolvedSends, resolvedReads } = entry;
      if (use.method !== ref.method || use.normalizedPath !== ref.normalizedPath) continue;

      // Whole-operation removal: every consumer calling it is affected.
      if (item.code === "ERR_BREAKING_OPERATION_REMOVED") {
        impacts.push({
          ...baseOf(entry),
          direction: "reads",
          code: item.code,
          severity: item.severity,
          fieldPath: null,
          matchedField: null,
          operationRef: item.operationRef,
          message: `${use.consumer} calls ${item.operationRef}, which no longer exists`,
          possibleUsage: false,
        });
        continue;
      }

      const fieldPath = item.fieldPath as string;
      const sends = resolvedSends.includes(fieldPath);
      const reads = resolvedReads.includes(fieldPath);

      switch (item.code) {
        case "ERR_BREAKING_FIELD_NOW_REQUIRED": {
          // Breaking for consumers that DON'T send the new required field.
          if (!sends) {
            impacts.push({
              ...baseOf(entry),
              direction: "sends",
              code: item.code,
              severity: item.severity,
              fieldPath,
              matchedField: null,
              operationRef: item.operationRef,
              message: `${use.consumer} sends ${listFields(use.sends)} to ${item.operationRef} and does not send the newly required \`${fieldPath}\``,
              possibleUsage: false,
            });
          }
          break;
        }
        case "ERR_BREAKING_ENUM_VALUE_REMOVED": {
          // L-5: conservative — the manifest names the field, so removal of an
          // accepted value may break it; wording states this is not proof.
          if (sends) {
            impacts.push({
              ...baseOf(entry),
              direction: "sends",
              code: item.code,
              severity: item.severity,
              fieldPath,
              matchedField: fieldPath,
              operationRef: item.operationRef,
              message: `${use.consumer} sends \`${fieldPath}\` to ${item.operationRef}; ${item.message}. This is a possible-usage match — the manifest lists the field without enumerating values, so removal of the value may break it`,
              possibleUsage: true,
            });
          }
          break;
        }
        default: {
          // Removed / now-optional / type-changed / sunset-expired findings:
          // the consumer that reads or sends the field is the one exposed.
          const sides = fieldSidesOf(baselineOp, candidateOp, fieldPath);
          const direction: ConsumerImpact["direction"] | null =
            sides.response && reads ? "reads" : sides.request && sends ? "sends" : null;
          if (direction !== null) {
            impacts.push({
              ...baseOf(entry),
              direction,
              code: item.code,
              severity: item.severity,
              fieldPath,
              matchedField: fieldPath,
              operationRef: item.operationRef,
              message: `${use.consumer} ${direction} \`${fieldPath}\` on ${item.operationRef}: ${item.message}`,
              possibleUsage: false,
            });
          }
        }
      }
    }
  }

  return impacts.sort(
    (left, right) =>
      left.consumer.localeCompare(right.consumer) ||
      left.operationRef.localeCompare(right.operationRef) ||
      (left.fieldPath ?? "").localeCompare(right.fieldPath ?? "") ||
      left.code.localeCompare(right.code),
  );
}

function baseOf(entry: ReturnType<typeof resolveUse>): {
  consumer: string;
  team: string | null;
  useId: number;
  provider: string;
  method: string;
  pathTemplate: string;
} {
  return {
    consumer: entry.use.consumer,
    team: entry.use.team,
    useId: entry.use.useId,
    provider: entry.use.provider,
    method: entry.use.method,
    pathTemplate: entry.use.pathTemplate,
  };
}

function listFields(fields: string[]): string {
  return fields.length <= 3
    ? fields.map((field) => `\`${field}\``).join(", ")
    : `${fields.length} fields`;
}

export interface ConsumerExposure {
  consumer: string;
  team: string | null;
  issues: ConsumerImpact[];
}

/**
 * Group impacts per consumer — the "exposed consumers" view of PLAN.md §7
 * (mobile-app 2 issues, payments-svc 1, partner-portal 1, notifications-svc
 * clean). Consumers without impact are listed with zero issues.
 */
export function groupImpactsByConsumer(
  impacts: ConsumerImpact[],
  consumerIndex: ConsumerUseIndex[],
): ConsumerExposure[] {
  const byConsumer = new Map<string, ConsumerExposure>();
  for (const use of consumerIndex) {
    if (!byConsumer.has(use.consumer)) {
      byConsumer.set(use.consumer, { consumer: use.consumer, team: use.team, issues: [] });
    }
  }
  for (const impact of impacts) {
    const exposure = byConsumer.get(impact.consumer);
    if (exposure !== undefined) exposure.issues.push(impact);
  }
  return [...byConsumer.values()].sort((left, right) =>
    left.consumer.localeCompare(right.consumer),
  );
}

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, describe, expect, it } from "vitest";

import { openDatabase, type Database } from "../src/db/database.js";
import { indexKit, findIndexedSpec, type KitIndexResult } from "../src/pipeline/indexKit.js";
import { diffWireIndexes } from "../src/diff/wireDiff.js";
import {
  attributeConsumerImpacts,
  groupImpactsByConsumer,
  type ConsumerImpact,
} from "../src/impact/consumerImpact.js";
import { finding, type Finding } from "../src/findings/codes.js";
import type { ConsumerUseIndex } from "../src/consumers/consumerIndex.js";

const KIT_ROOT = fileURLToPath(new URL("../../", import.meta.url));
const AS_OF = new Date(Date.UTC(2026, 10, 18));

const dirs: string[] = [];
const handles: Array<Database> = [];
afterAll(() => {
  while (handles.length) handles.pop()?.close();
  while (dirs.length) rmSync(dirs.pop() as string, { recursive: true, force: true });
});

let cached: KitIndexResult | undefined;
function indexed(): KitIndexResult {
  if (cached) return cached;
  const dir = mkdtempSync(join(tmpdir(), "cg-impact-"));
  dirs.push(dir);
  const { db } = openDatabase({ path: join(dir, "cg.db") });
  handles.push(db);
  cached = indexKit(KIT_ROOT, db);
  return cached;
}

function specOf(service: string, prefix: string) {
  const spec = findIndexedSpec(indexed(), service, prefix);
  expect(spec, `missing ${service}/${prefix}`).toBeDefined();
  return spec as NonNullable<typeof spec>;
}

function impactsFor(service: string, basePrefix: string, candPrefix: string): ConsumerImpact[] {
  const baseline = specOf(service, basePrefix);
  const candidate = specOf(service, candPrefix);
  const findings = diffWireIndexes(baseline.operations, candidate.operations, {
    asOfDate: AS_OF,
  });
  return attributeConsumerImpacts({
    service,
    findings,
    baselineOperations: baseline.operations,
    candidateOperations: candidate.operations,
    consumerIndex: indexed().consumers,
  });
}

function consumersWithIssues(impacts: ConsumerImpact[]): string[] {
  return [...new Set(impacts.map((impact) => impact.consumer))].sort();
}

describe("mobile-app: quote premium.breakdown[].amount (matrix row 3)", () => {
  const impacts = impactsFor("quote-api", "2-", "3-");

  it("attributes the amount removal to mobile-app on POST /quotes", () => {
    const mobile = impacts.filter((impact) => impact.consumer === "mobile-app");
    expect(mobile).toHaveLength(1);
    expect(mobile[0]).toMatchObject({
      code: "ERR_BREAKING_FIELD_REMOVED",
      severity: "blocking",
      direction: "reads",
      fieldPath: "premium.breakdown[].amount",
      operationRef: "POST /quotes",
      team: "Mobile",
    });
    expect(mobile[0]?.message).toContain("mobile-app");
  });

  it("does not expose partner-portal or notifications-svc, which never read amount", () => {
    expect(consumersWithIssues(impacts)).toEqual(["mobile-app"]);
  });

  it("reports no consumer impact on the internal pricing-cache op (PO-1/L-1)", () => {
    expect(impacts.filter((impact) => impact.operationRef.includes("pricing-cache"))).toEqual([]);
  });

  it("the EXPIRED enum warning creates no consumer impact", () => {
    expect(impacts.filter((impact) => impact.code === "WARN_ENUM_VALUE_ADDED")).toEqual([]);
  });
});

describe("mobile-app: claims amountApproved becoming optional (matrix row 12)", () => {
  const impacts = impactsFor("claims-api", "1-", "4-");

  it("attributes the required-drop to mobile-app on GET /claims/{claimId}", () => {
    const mobile = impacts.filter((impact) => impact.consumer === "mobile-app");
    expect(mobile).toHaveLength(1);
    expect(mobile[0]).toMatchObject({
      code: "ERR_BREAKING_FIELD_NOW_OPTIONAL",
      direction: "reads",
      fieldPath: "amountApproved",
      operationRef: "GET /claims/{claimId}",
    });
  });

  it("notifications-svc, which reads only claimId and status, is not exposed", () => {
    expect(consumersWithIssues(impacts)).toEqual(["mobile-app"]);
  });
});

describe("payments-svc: legacyCode sunset removal (matrix rows 6–7)", () => {
  const impacts = impactsFor("policy-api", "2-", "3-");

  it("attributes the past-sunset removal to payments-svc", () => {
    const payments = impacts.filter((impact) => impact.consumer === "payments-svc");
    expect(payments).toHaveLength(1);
    expect(payments[0]).toMatchObject({
      code: "ERR_SUNSET_REMOVAL_EXPIRED",
      severity: "blocking",
      direction: "reads",
      fieldPath: "legacyCode",
      operationRef: "GET /policies/{policyId}",
      team: "Payments",
    });
  });

  it("holder.phone removal exposes nobody — no manifest reads it", () => {
    expect(impacts.filter((impact) => impact.fieldPath === "holder.phone")).toEqual([]);
    expect(consumersWithIssues(impacts)).toEqual(["payments-svc"]);
  });
});

describe("partner-portal: requestedBy and the VEHICLE enum drop (matrix row 8)", () => {
  const impacts = impactsFor("policy-api", "2-", "4-");

  it("breaks partner-portal for the new required requestedBy it does not send", () => {
    const requestedBy = impacts.find(
      (impact) =>
        impact.consumer === "partner-portal" && impact.fieldPath === "requestedBy",
    );
    expect(requestedBy).toMatchObject({
      code: "ERR_BREAKING_FIELD_NOW_REQUIRED",
      direction: "sends",
      possibleUsage: false,
    });
    expect(requestedBy?.message).toMatch(/does not send the newly required `requestedBy`/);
  });

  it("reports the VEHICLE enum removal on the sent `type` field as possible-usage (L-5)", () => {
    const enumImpact = impacts.find(
      (impact) =>
        impact.consumer === "partner-portal" &&
        impact.code === "ERR_BREAKING_ENUM_VALUE_REMOVED",
    );
    expect(enumImpact).toMatchObject({
      direction: "sends",
      fieldPath: "type",
      possibleUsage: true,
      severity: "blocking",
    });
    expect(enumImpact?.message).toMatch(/VEHICLE/);
    expect(enumImpact?.message).toMatch(/possible-usage match/);
  });

  it("payments-svc is still exposed on legacyCode through the cascade", () => {
    expect(
      impacts.find((i) => i.consumer === "payments-svc" && i.code === "ERR_SUNSET_REMOVAL_EXPIRED"),
    ).toBeDefined();
  });

  it("notifications-svc, which uses no changed operation, stays clean", () => {
    expect(impacts.filter((impact) => impact.consumer === "notifications-svc")).toEqual([]);
  });
});

describe("alias-correct matching (D-3)", () => {
  it("mobile-app's `id` sends still resolve after the quoteId rename", () => {
    // The quote 1.1.0→2.0.0 diff made no change to the renamed path param;
    // a hypothetical required-param finding on `quoteId` must NOT expose the
    // manifest that sends `id` — the alias map rewrites it to `quoteId`.
    const baseline = specOf("quote-api", "2-");
    const candidate = specOf("quote-api", "3-");
    const impacts = attributeConsumerImpacts({
      service: "quote-api",
      findings: [
        finding("ERR_BREAKING_FIELD_NOW_REQUIRED", "request field `quoteId` is now required", {
          operationRef: "GET /quotes/{quoteId}",
          fieldPath: "quoteId",
        }),
      ],
      baselineOperations: baseline.operations,
      candidateOperations: candidate.operations,
      consumerIndex: indexed().consumers,
    });
    // mobile-app and notifications-svc both send the param (as `id`) → unaffected.
    expect(impacts).toEqual([]);
  });
});

describe("internal-endpoint exclusion proven directly (PO-1/L-1)", () => {
  it("skips consumer impact even for a synthetic consumer calling the internal op", () => {
    const internalUser: ConsumerUseIndex = {
      useId: 999,
      consumer: "cache-buster",
      team: "Infra",
      provider: "quote-api",
      method: "DELETE",
      pathTemplate: "/internal/pricing-cache",
      normalizedPath: "/internal/pricing-cache",
      sends: ["region"],
      reads: [],
    };
    // A BLOCKING finding on the internal op (diff downgrades these to notes;
    // the engine must exclude them again regardless).
    const impacts = attributeConsumerImpacts({
      service: "quote-api",
      findings: [
        finding("ERR_BREAKING_FIELD_NOW_REQUIRED", "request field `region` is new and required", {
          operationRef: "DELETE /internal/pricing-cache",
          fieldPath: "region",
        }),
      ],
      baselineOperations: specOf("quote-api", "2-").operations,
      candidateOperations: specOf("quote-api", "3-").operations,
      consumerIndex: [...indexed().consumers, internalUser],
    });
    expect(impacts).toEqual([]);
  });
});

describe("operation removal exposes every caller (rulebook)", () => {
  it("attributes a removed operation to both quote readers", () => {
    const impacts = attributeConsumerImpacts({
      service: "quote-api",
      findings: [
        finding("ERR_BREAKING_OPERATION_REMOVED", "operation GET /quotes/{} was removed", {
          operationRef: "GET /quotes/{}",
        }),
      ],
      baselineOperations: specOf("quote-api", "1-").operations,
      candidateOperations: specOf("quote-api", "2-").operations,
      consumerIndex: indexed().consumers,
    });
    expect(consumersWithIssues(impacts)).toEqual(["mobile-app", "notifications-svc"]);
    expect(impacts[0]?.message).toMatch(/calls GET \/quotes\/\{\}, which no longer exists/);
  });
});

describe("consumers that send a new required field are NOT exposed", () => {
  it("skips manifests that already send the field", () => {
    const impacts = attributeConsumerImpacts({
      service: "quote-api",
      findings: [
        finding("ERR_BREAKING_FIELD_NOW_REQUIRED", "request field `vehicle.make` is now required", {
          operationRef: "POST /quotes",
          fieldPath: "vehicle.make",
        }),
      ],
      baselineOperations: specOf("quote-api", "1-").operations,
      candidateOperations: specOf("quote-api", "2-").operations,
      consumerIndex: indexed().consumers,
    });
    // mobile-app and partner-portal both send vehicle.make.
    expect(impacts).toEqual([]);
  });
});

describe("exposed-consumer grouping (PLAN §7 view)", () => {
  it("lists every consumer, with issue counts, notifications-svc clean", () => {
    const quoteImpacts = impactsFor("quote-api", "2-", "3-");
    const claimsImpacts = impactsFor("claims-api", "1-", "4-");
    const all = [...quoteImpacts, ...claimsImpacts];
    const grouped = groupImpactsByConsumer(all, indexed().consumers);

    expect(grouped.map((group) => [group.consumer, group.issues.length])).toEqual([
      ["mobile-app", 2],
      ["notifications-svc", 0],
      ["partner-portal", 0],
      ["payments-svc", 0],
    ]);
    expect(grouped.find((group) => group.consumer === "mobile-app")?.team).toBe("Mobile");
  });
});

/**
 * Publication gate (PLAN.md §5, locked decisions L-1/L-2/L-4, D-4).
 *
 * For one candidate spec version the gate decides, in a single SQLite
 * transaction:
 * 1. Duplicate version (L-2)? A version already reserved by a `published` or
 *    `blocked` intake is rejected with `ERR_DUPLICATE_VERSION` and the locked
 *    guidance — the row is still recorded, as `rejected`.
 * 2. Invalid spec? Blocked for validity reasons, a distinct reason code from
 *    breaking changes (`ERR_INVALID_SPEC`).
 * 3. Otherwise diff against the last *published* version (D-4), attribute
 *    consumer impact, and apply the gate mode:
 *    - `consumer` (L-1 default): block when a known consumer is impacted or a
 *      past-sunset field was removed (L-4); unconsumed public breaking changes
 *      publish with recorded `WARN_UNCONSUMED_BREAKING`.
 *    - `strict`: any blocking finding blocks.
 * The verdict, every finding row (with consumer attribution), and one audit
 * event commit atomically — a mid-transaction failure rolls all of it back.
 */

import type { Database } from "../db/database.js";
import {
  DUPLICATE_VERSION_GUIDANCE,
  finding,
  type Finding,
  type FindingCode,
} from "../findings/codes.js";
import type { GateMode } from "../config.js";
import { diffWireIndexes } from "../diff/wireDiff.js";
import {
  attributeConsumerImpacts,
  type ConsumerImpact,
} from "../impact/consumerImpact.js";
import type { ConsumerUseIndex } from "../consumers/consumerIndex.js";
import type { IndexedOperation } from "../wire/operationIndex.js";

export type GateOutcome = "published" | "blocked" | "rejected";

/** Everything the pipeline knows about one candidate version. */
export interface GateCandidate {
  service: string;
  version: string;
  /** Kit-relative source path, e.g. `specs/quote-api/1-initial.yaml`. */
  sourceFile: string;
  /** Filename-prefix order within the service. */
  order: number;
  valid: boolean;
  /** Validation findings recorded at intake (e.g. ERR_INVALID_SPEC). */
  intakeFindings: Finding[];
  /** Wire index of this candidate. */
  operations: IndexedOperation[];
}

export interface GateOptions {
  mode: GateMode;
  asOfDate: Date;
  consumerIndex: ConsumerUseIndex[];
  /** All versions of the candidate's service in publication order, so the
   * last-published baseline can be picked from live DB statuses (D-4). */
  serviceVersions: GateCandidate[];
  /** Test seam: invoked inside the transaction; throwing simulates a DB
   * failure so rollback of verdict + findings + audit can be proven. */
  fault?: () => void;
}

export interface GateVerdict {
  outcome: GateOutcome;
  /** Reason codes stored with the version; ordered, deduplicated. */
  reasonCodes: FindingCode[];
  /** Findings the gate itself produced (duplicate note, unconsumed warnings). */
  gateFindings: Finding[];
  /** Consumer impacts of the diff (empty unless blocked by impact). */
  impacts: ConsumerImpact[];
  /** Which baseline rule applied. */
  baseline: "first" | "previous";
  /** Registry row id of the decided version. */
  specVersionId: number;
}

/** Statuses that reserve a version number (locked decision L-2). */
const RESERVING_STATUSES = ["published", "blocked"] as const;

interface RowIds {
  serviceId: number;
  specVersionId: number;
}

function locate(db: Database, candidate: GateCandidate): RowIds {
  const row = db
    .prepare(
      `SELECT sv.id AS specVersionId, s.id AS serviceId
       FROM spec_versions sv
       JOIN services s ON s.id = sv.service_id
       WHERE s.name = ? AND sv.version = ? AND sv.source_file = ?`,
    )
    .get(candidate.service, candidate.version, candidate.sourceFile) as RowIds | undefined;
  if (row === undefined) {
    throw new Error(
      `intake row missing for ${candidate.service} ${candidate.version} (${candidate.sourceFile})`,
    );
  }
  return row;
}

/** The earlier reserved row that occupies this version number, if any (L-2). */
function duplicateOf(db: Database, ids: RowIds, candidate: GateCandidate) {
  return db
    .prepare(
      `SELECT sv.id AS id, sv.source_file AS sourceFile, sv.status AS status
       FROM spec_versions sv
       WHERE sv.service_id = ? AND sv.version = ? AND sv.id != ?
         AND sv.status IN (${RESERVING_STATUSES.map(() => "?").join(", ")})
       ORDER BY sv.source_file`,
    )
    .get(
      ids.serviceId,
      candidate.version,
      ids.specVersionId,
      ...RESERVING_STATUSES,
    ) as { id: number; sourceFile: string; status: string } | undefined;
}

/** Last published version of the service before the candidate (D-4). */
function lastPublishedBaseline(
  db: Database,
  ids: RowIds,
  options: GateOptions,
  candidate: GateCandidate,
): { version: GateCandidate } | undefined {
  const earlier = options.serviceVersions
    .filter((version) => version.order < candidate.order)
    .sort((left, right) => right.order - left.order);
  if (earlier.length === 0) return undefined;

  const published = db
    .prepare(
      `SELECT source_file AS sourceFile FROM spec_versions
       WHERE service_id = ? AND status = 'published'`,
    )
    .all(ids.serviceId) as Array<{ sourceFile: string }>;
  const publishedFiles = new Set(published.map((row) => row.sourceFile));

  const baseline = earlier.find((version) => publishedFiles.has(version.sourceFile));
  return baseline === undefined ? undefined : { version: baseline };
}

/** Pure verdict logic: findings + impacts + mode → outcome and reason codes. */
export function decide(input: {
  mode: GateMode;
  duplicate: { sourceFile: string; status: string } | undefined;
  valid: boolean;
  intakeFindings: Finding[];
  diffFindings: Finding[];
  impacts: ConsumerImpact[];
}): { outcome: GateOutcome; reasonCodes: FindingCode[]; gateFindings: Finding[] } {
  // 1. Version reservation (L-2) outranks everything: the number is taken.
  if (input.duplicate !== undefined) {
    const dup = finding(
      "ERR_DUPLICATE_VERSION",
      `version is already reserved by ${input.duplicate.sourceFile} (${input.duplicate.status}); ${DUPLICATE_VERSION_GUIDANCE}`,
    );
    return { outcome: "rejected", reasonCodes: ["ERR_DUPLICATE_VERSION"], gateFindings: [dup] };
  }

  // 2. Validity is its own block reason, distinct from breaking changes.
  if (!input.valid) {
    const codes = dedupe(input.intakeFindings.map((item) => item.code));
    return { outcome: "blocked", reasonCodes: codes, gateFindings: [] };
  }

  // 3. Breaking-change verdict under the gate mode.
  const blocking = input.diffFindings.filter((item) => item.severity === "blocking");
  const impactedCodes = new Set(input.impacts.map((impact) => impact.code + impact.operationRef + impact.fieldPath));
  const isImpacted = (item: Finding): boolean =>
    impactedCodes.has(item.code + item.operationRef + item.fieldPath);
  // A past-sunset removal is hard-breaking regardless of consumers (L-4/PO-3).
  const isSunsetExpiry = (item: Finding): boolean => item.code === "ERR_SUNSET_REMOVAL_EXPIRED";

  const reasonSet = new Set<FindingCode>();
  const gateFindings: Finding[] = [];

  for (const item of blocking) {
    if (input.mode === "strict") {
      reasonSet.add(item.code);
    } else if (isImpacted(item) || isSunsetExpiry(item)) {
      reasonSet.add(item.code);
    } else {
      // Unconsumed public breaking change: publish with a recorded warning (L-1).
      gateFindings.push(
        finding(
          "WARN_UNCONSUMED_BREAKING",
          `unconsumed breaking change: ${item.message}`,
          { operationRef: item.operationRef, fieldPath: item.fieldPath },
        ),
      );
    }
  }

  const outcome: GateOutcome = reasonSet.size > 0 ? "blocked" : "published";
  return { outcome, reasonCodes: [...reasonSet], gateFindings };
}

function dedupe<T>(items: T[]): T[] {
  return [...new Set(items)];
}

function replaceFindings(
  db: Database,
  specVersionId: number,
  rows: Array<{ item: Finding; consumerId: number | null }>,
): void {
  db.prepare("DELETE FROM findings WHERE spec_version_id = ?").run(specVersionId);
  const insert = db.prepare(
    `INSERT INTO findings (spec_version_id, code, severity, operation_ref, field_path, consumer_id, message)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
  );
  for (const row of rows) {
    insert.run(
      specVersionId,
      row.item.code,
      row.item.severity,
      row.item.operationRef ?? null,
      row.item.fieldPath ?? null,
      row.consumerId,
      row.item.message,
    );
  }
}

/**
 * Run the gate for one candidate and persist the verdict atomically.
 * The caller (startup pipeline, Phase 7) processes candidates in filename
 * order so each sees the live statuses of the ones before it.
 */
export function runPublicationGate(
  db: Database,
  candidate: GateCandidate,
  options: GateOptions,
): GateVerdict {
  const write = db.transaction((): GateVerdict => {
    const ids = locate(db, candidate);
    const duplicate = duplicateOf(db, ids, candidate);
    const baselineEntry = lastPublishedBaseline(db, ids, options, candidate);

    // Diff and impact only make sense for a valid, non-duplicate candidate.
    const diffFindings: Finding[] =
      duplicate === undefined && candidate.valid && baselineEntry !== undefined
        ? diffWireIndexes(baselineEntry.version.operations, candidate.operations, {
            asOfDate: options.asOfDate,
          })
        : [];
    const impacts: ConsumerImpact[] =
      duplicate === undefined && candidate.valid && baselineEntry !== undefined
        ? attributeConsumerImpacts({
            service: candidate.service,
            findings: diffFindings,
            baselineOperations: baselineEntry.version.operations,
            candidateOperations: candidate.operations,
            consumerIndex: options.consumerIndex,
          })
        : [];

    const verdictPart = decide({
      mode: options.mode,
      duplicate,
      valid: candidate.valid,
      intakeFindings: candidate.intakeFindings,
      diffFindings,
      impacts,
    });

    // Persist: status + reason + decided_at, findings (intake + gate + impact
    // attributions), one audit event — all in this one transaction.
    db.prepare(
      `UPDATE spec_versions
       SET status = ?, outcome_reason_code = ?, decided_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
       WHERE id = ?`,
    ).run(
      verdictPart.outcome,
      verdictPart.reasonCodes.join(","),
      ids.specVersionId,
    );

    const consumerIds = new Map<string, number>(
      (db.prepare("SELECT id, name FROM consumers").all() as Array<{ id: number; name: string }>).map(
        (row) => [row.name, row.id],
      ),
    );

    const findingRows: Array<{ item: Finding; consumerId: number | null }> = [
      ...candidate.intakeFindings.map((item) => ({ item, consumerId: null })),
      ...verdictPart.gateFindings.map((item) => ({ item, consumerId: null })),
      ...diffFindings.map((item) => ({ item, consumerId: null })),
      ...impacts.map((impact) => ({
        item: finding(
          impact.code,
          impact.message,
          { operationRef: impact.operationRef, fieldPath: impact.fieldPath ?? undefined },
        ),
        consumerId: consumerIds.get(impact.consumer) ?? null,
      })),
    ];
    replaceFindings(db, ids.specVersionId, findingRows);

    db.prepare(
      `INSERT INTO events (kind, service, version, outcome, detail)
       VALUES ('gate_decision', ?, ?, ?, ?)`,
    ).run(
      candidate.service,
      candidate.version,
      verdictPart.outcome,
      JSON.stringify({
        sourceFile: candidate.sourceFile,
        mode: options.mode,
        baseline: baselineEntry === undefined ? "first" : baselineEntry.version.sourceFile,
        reasonCodes: verdictPart.reasonCodes,
        impactedConsumers: dedupe(impacts.map((impact) => impact.consumer)),
        diffFindings: diffFindings.length,
      }),
    );

    options.fault?.();

    return {
      outcome: verdictPart.outcome,
      reasonCodes: verdictPart.reasonCodes,
      gateFindings: verdictPart.gateFindings,
      impacts,
      baseline: baselineEntry === undefined ? "first" : "previous",
      specVersionId: ids.specVersionId,
    };
  });

  return write();
}

/** Build gate candidates from the Phase 2 index plus Phase 1 validity data. */
export function candidateOf(index: {
  specs: Array<{
    service: string;
    version: string;
    sourceFile: string;
    order: number;
    operations: IndexedOperation[];
  }>;
}, validity: Map<string, { valid: boolean; issues: Finding[] }>, keyOf: (spec: { service: string; sourceFile: string }) => string): GateCandidate[] {
  return index.specs.map((spec) => {
    const state = validity.get(keyOf(spec));
    return {
      service: spec.service,
      version: spec.version,
      sourceFile: spec.sourceFile,
      order: spec.order,
      valid: state?.valid ?? false,
      intakeFindings: state?.issues ?? [],
      operations: spec.operations,
    };
  });
}

