  "name": "contract-guard-client",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc --noEmit && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "lucide-react": "^0.545.0",
    "react": "^19.2.0",
    "react-dom": "^19.2.0"
  },
  "devDependencies": {
    "@tailwindcss/vite": "^4.1.0",
    "@types/react": "^19.2.0",
    "@types/react-dom": "^19.2.0",
    "@vitejs/plugin-react": "^5.0.0",
    "tailwindcss": "^4.1.0",
    "typescript": "^5.9.0",
    "vite": "^7.1.0"
  }
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";

// Dev server proxies the API to the Contract Guard backend (PORT, default 5000),
// so the SPA talks to the same origin in dev and production alike.
export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    proxy: {
      "/api": {
        target: process.env.CG_API_TARGET ?? "http://localhost:5000",
        changeOrigin: true,
      },
    },
  },
  build: {
    outDir: "dist",
    sourcemap: true,
  },
});

@import "tailwindcss";

@theme {
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

body {
  @apply bg-slate-950 text-slate-100 antialiased;
}

/** Shapes returned by the Contract Guard API (PLAN.md §9). */

export interface ServiceSummary {
  name: string;
  title: string | null;
  owner: string | null;
  description: string | null;
  latestPublished: string | null;
  versions: string[];
}

export interface VersionRow {
  id: number;
  version: string;
  status: "published" | "blocked" | "rejected" | "staged" | "invalid";
